+</head>
+<body>
+  <div id="app">
+    <header class="hud-header" id="hudHeader">
+      <div class="hud-top-row">
+        <div class="brand-group">
+          <div class="brand-badge"></div>
+          <h1>Gemini 4 Argon</h1>
+          <span class="subtitle-tag">2D Rigid-Body Crash Sandbox</span>
+          <div id="statusPill" class="status-pill">
+            <span class="status-dot"></span>
+            <span id="statusText">Ready</span>
+          </div>
+        </div>
+
+        <div class="telemetry-strip">
+          <div class="telemetry-card">
+            <span class="telemetry-label">Car Speed</span>
+            <div class="telemetry-value">
+              <span id="telSpeed">0.0</span>
+              <span class="telemetry-sub" id="telSpeedKmh">m/s (0 km/h)</span>
+            </div>
+          </div>
+          <div class="telemetry-card">
+            <span class="telemetry-label">Elapsed Time</span>
