+          </div>
+          <input type="range" id="inpBrickMass" min="0.5" max="12" step="0.1" value="2.5" />
+          <div class="setting-limits"><span>0.5 kg</span><span>2.5 kg default</span><span>12.0 kg</span></div>
+        </div>
+      </div>
+
+      <!-- Active Fixed Baseline Constants Readout -->
+      <div class="specs-strip">
+        <div class="specs-list">
+          <span class="spec-item">Car Mass: <strong>1,250 kg</strong></span>
+          <span class="spec-item">Car Size: <strong>4.20 m &times; 1.45 m</strong></span>
+          <span class="spec-item">Brick Size: <strong>0.50 m &times; 0.24 m</strong></span>
+          <span class="spec-item">Gravity: <strong>9.81 m/s&sup2;</strong></span>
+          <span class="spec-item">Brick &mu;: <strong>0.72</strong></span>
+          <span class="spec-item">Brick Restitution: <strong>0.18</strong></span>
+          <span class="spec-item">Ground &mu;: <strong>0.85</strong></span>
+          <span class="spec-item">Scale: <strong id="specScale">80 px/m</strong></span>
+        </div>
+        <div class="specs-list">
+          <span class="spec-item">Peak G: <strong id="telPeakG">0.0 G</strong></span>
