+
+  <script>
+    (function () {
+      "use strict";
+
+      // =========================================================================
+      // MANDATORY DEFAULT EXPERIMENT VALUES & CONSTANTS
+      // =========================================================================
+      const DEFAULTS = Object.freeze({
+        carSpeed: 22,            // m/s (range: 5 to 45)
+        wallColumns: 12,         // bricks wide (range: 4 to 24)
+        wallRows: 8,             // bricks tall (range: 3 to 16)
+        wallDepthLayers: 2,      // layers thick (range: 1 to 5)
+        brickMass: 2.5,          // kg per brick (range: 0.5 to 12)
+        brickWidth: 0.50,        // m
+        brickHeight: 0.24,       // m
+        gravity: 9.81,           // m/s^2
+        brickFriction: 0.72,     // coefficient
+        brickRestitution: 0.18,  // coefficient
+        carMass: 1250,           // kg
+        carWidth: 4.2,           // m
+        carHeight: 1.45,         // m
+        groundFriction: 0.85,    // coefficient
+        scale: 80                // pixels per meter
+      });
+
+      const settings = {
+        carSpeed: DEFAULTS.carSpeed,
+        wallColumns: DEFAULTS.wallColumns,
+        wallRows: DEFAULTS.wallRows,
+        wallDepthLayers: DEFAULTS.wallDepthLayers,
+        brickMass: DEFAULTS.brickMass
+      };
+
+      // =========================================================================
+      // DETERMINISTIC SEEDED PRNG (VISUALS ONLY - NEVER USED IN PHYSICS)
+      // =========================================================================
+      let visualSeed = 0x5F3759DF;
+      function resetVisualRNG() {
+        visualSeed = 0x5F3759DF;
+      }
+      function nextVisualRand() {
+        visualSeed |= 0;
+        visualSeed = (visualSeed + 0x6D2B79F5) | 0;
+        let t = Math.imul(visualSeed ^ (visualSeed >>> 15), 1 | visualSeed);
+        t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
+        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
+      }
+
+      // =========================================================================
+      // DOM REFERENCES
+      // =========================================================================
+      const canvas = document.getElementById("simCanvas");
+      const ctx = canvas.getContext("2d");
+      const stage = document.getElementById("canvasStage");
+
+      const btnTest = document.getElementById("btnTest");
+      const btnReset = document.getElementById("btnReset");
+      const btnDefaults = document.getElementById("btnDefaults");
+
+      const inpCarSpeed = document.getElementById("inpCarSpeed");
+      const inpWallCols = document.getElementById("inpWallCols");
+      const inpWallRows = document.getElementById("inpWallRows");
+      const inpWallLayers = document.getElementById("inpWallLayers");
+      const inpBrickMass = document.getElementById("inpBrickMass");
+
+      const valCarSpeed = document.getElementById("valCarSpeed");
+      const valWallCols = document.getElementById("valWallCols");
+      const valWallRows = document.getElementById("valWallRows");
+      const valWallLayers = document.getElementById("valWallLayers");
+      const valBrickMass = document.getElementById("valBrickMass");
+
+      const statusPill = document.getElementById("statusPill");
+      const statusText = document.getElementById("statusText");
+      const telSpeed = document.getElementById("telSpeed");
+      const telSpeedKmh = document.getElementById("telSpeedKmh");
+      const telTime = document.getElementById("telTime");
+      const telMoving = document.getElementById("telMoving");
+      const telTotalBricks = document.getElementById("telTotalBricks");
+      const telDisplaced = document.getElementById("telDisplaced");
+      const telDisplacedPct = document.getElementById("telDisplacedPct");
+      const telWallMass = document.getElementById("telWallMass");
+      const telPeakG = document.getElementById("telPeakG");
+      const telImpulse = document.getElementById("telImpulse");
+
+      // =========================================================================
+      // SIMULATION STATE
+      // =========================================================================
+      const FIXED_DT = 1 / 60;
+      const SUBSTEPS = 8;
+      const SUB_DT = FIXED_DT / SUBSTEPS;
+      const SOLVER_ITERATIONS = 10;
+
+      const TRACK_START_X = 0.75; // left margin in meters
+      const RUNWAY_GAP = 3.25;    // distance from front bumper to wall front face in meters
+
+      let simState = "ready"; // "ready" | "running" | "settled"
+      let simTime = 0;
+      let impactOccurred = false;
+      let settledTimer = 0;
+      let peakGForce = 0;
+      let totalMomentumTransferred = 0;
+      let cameraShake = 0;
+      let cameraX = 0;
+
+      let car = null;
+      let bricks = [];
+      let bricksByLayer = [];
+      let mortarJoints = [];
+      let depthCouplings = [];
+
+      // Visual-only effects
+      let dustParticles = [];
+      let skidMarks = [];
+
+      // =========================================================================
+      // INITIALIZE / RESET SCENE
+      // =========================================================================
+      function createCar() {
+        const w = DEFAULTS.carWidth;
+        const h = DEFAULTS.carHeight;
+        const m = DEFAULTS.carMass;
+        const inertia = (m * (w * w + h * h)) / 12;
+
+        const startCenterX = TRACK_START_X + w * 0.5;
+        const restCenterY = h * 0.5;
+
+        return {
+          x: startCenterX,
+          y: restCenterY,
+          vx: 0,
+          vy: 0,
+          angle: 0,
+          omega: 0,
+          w: w,
+          h: h,
+          hw: w * 0.5,
+          hh: h * 0.5,
+          mass: m,
+          invMass: 1 / m,
+          inertia: inertia,
+          invInertia: 1 / inertia,
+          targetSpeed: settings.carSpeed,
+          wheelAngle: 0,
+          crumple: 0,
+          airbagDeployed: false,
+          dummyPitch: 0,
+          dummyPitchVel: 0,
+          prevVx: 0
+        };
+      }
+
+      function getCarHullVertices(c) {
+        // Aerodynamic sedan convex hull in local coordinates around (c.x, c.y)
+        // Total width = 4.2m (-2.1 to +2.1), total height = 1.45m (-0.725 to +0.725)
+        const hw = c.hw;
+        const hh = c.hh;
+        const crumple = c.crumple;
+        const frontX = hw - crumple;
+        const hoodTopY = -hh + 0.86 + crumple * 0.18;
+
+        const localPts = [
+          { x: -hw,          y: -hh + 0.05 }, // 0: rear bottom
+          { x: frontX - 0.06, y: -hh + 0.03 }, // 1: front air-dam bottom (3cm clearance engages row 0)
+          { x: frontX,       y: -hh + 0.22 }, // 2: front bumper nose
+          { x: frontX - 0.04, y: hoodTopY   }, // 3: hood leading edge
+          { x: 0.72,         y: hh         }, // 4: windshield top / roof front
+          { x: -0.95,        y: hh         }, // 5: roof rear
+          { x: -hw,          y: -hh + 0.92 }  // 6: rear decklid / trunk
+        ];
+
+        const cos = Math.cos(c.angle);
+        const sin = Math.sin(c.angle);
+        const worldPts = new Array(localPts.length);
+        for (let i = 0; i < localPts.length; i++) {
+          const lx = localPts[i].x;
+          const ly = localPts[i].y;
+          worldPts[i] = {
+            x: c.x + lx * cos - ly * sin,
+            y: c.y + lx * sin + ly * cos
+          };
+        }
+        return worldPts;
+      }
+
+      function createWall() {
+        bricks = [];
+        bricksByLayer = [];
+        mortarJoints = [];
+        depthCouplings = [];
+
+        const cols = settings.wallColumns;
+        const rows = settings.wallRows;
+        const layers = settings.wallDepthLayers;
+        const bw = DEFAULTS.brickWidth;
+        const bh = DEFAULTS.brickHeight;
+        const bm = settings.brickMass;
+        const bInertia = (bm * (bw * bw + bh * bh)) / 12;
+
+        const wallFrontX = TRACK_START_X + DEFAULTS.carWidth + RUNWAY_GAP;
+        // Overlapping depth layers offset slightly in X so additional layers physically thicken the wall barrier
+        const layerStepX = layers > 1 ? 0.09 : 0;
+
+        let idCounter = 0;
+        const grid = [];
+
+        for (let l = 0; l < layers; l++) {
+          const layerArr = [];
+          const layerGrid = [];
+          const layerOffsetX = l * layerStepX;
+
+          for (let r = 0; r < rows; r++) {
+            const rowGrid = [];
+            // Running bond: alternating seams between even and odd rows
+            // Layer parity also alternates seam alignment across wythes like real Flemish/English bond
+            const isStaggeredRow = ((r + l) % 2) === 1;
+            const staggerX = isStaggeredRow ? (bw * 0.5) : 0;
+
+            for (let c = 0; c < cols; c++) {
+              const cx = wallFrontX + layerOffsetX + staggerX + c * bw + bw * 0.5;
+              const cy = r * bh + bh * 0.5;
+
+              // Deterministic terracotta shade variation per (l, r, c)
+              const hash = ((l * 131 + r * 37 + c * 17) & 0xff) / 255;
+
+              const brick = {
+                id: idCounter++,
+                layer: l,
+                row: r,
+                col: c,
+                x: cx,
+                y: cy,
+                initialX: cx,
+                initialY: cy,
+                vx: 0,
+                vy: 0,
+                angle: 0,
+                omega: 0,
+                cos: 1,
+                sin: 0,
+                w: bw,
+                h: bh,
+                hw: bw * 0.5,
+                hh: bh * 0.5,
+                mass: bm,
+                invMass: 1 / bm,
+                inertia: bInertia,
+                invInertia: 1 / bInertia,
+                shade: hash,
+                sleepTimer: 0,
+                sleeping: false,
+                brokenBonds: 0,
+                totalBonds: 0
+              };
+
+              bricks.push(brick);
+              layerArr.push(brick);
+              rowGrid.push(brick);
+            }
+            layerGrid.push(rowGrid);
+          }
+          bricksByLayer.push(layerArr);
+          grid.push(layerGrid);
+        }
+
+        // Create cohesive-brittle mortar joints within each layer
+        for (let l = 0; l < layers; l++) {
+          for (let r = 0; r < rows; r++) {
+            for (let c = 0; c < cols; c++) {
+              const bA = grid[l][r][c];
+
+              // Horizontal neighbor in same row
+              if (c + 1 < cols) {
+                const bB = grid[l][r][c + 1];
+                addMortarJoint(bA, bB, 1.0);
+              }
+
+              // Vertical neighbors in row above
+              if (r + 1 < rows) {
+                for (let cAbove = 0; cAbove < cols; cAbove++) {
+                  const bAbove = grid[l][r + 1][cAbove];
+                  const dx = Math.abs(bAbove.x - bA.x);
+                  if (dx < bw * 0.78) {
+                    addMortarJoint(bA, bAbove, 1.15);
+                  }
+                }
+              }
+            }
+          }
+        }
+
+        // Create inter-layer tie couplings between overlapping wythes (depth layers)
+        for (let l = 0; l < layers - 1; l++) {
+          for (let r = 0; r < rows; r++) {
+            for (let c = 0; c < cols; c++) {
+              const bFront = grid[l][r][c];
+              const bBack = grid[l + 1][r][c];
+              depthCouplings.push({
+                a: bFront,
+                b: bBack,
+                dx0: bBack.x - bFront.x,
+                dy0: bBack.y - bFront.y,
+                broken: false
+              });
+              bFront.totalBonds++;
+              bBack.totalBonds++;
+            }
+          }
+        }
+      }
+
+      function addMortarJoint(a, b, strengthFactor) {
+        mortarJoints.push({
+          a: a,
+          b: b,
+          dx0: b.x - a.x,
+          dy0: b.y - a.y,
+          strength: strengthFactor,
+          broken: false
+        });
+        a.totalBonds++;
+        b.totalBonds++;
+      }
+
+      function resetExperiment() {
+        resetVisualRNG();
+        simState = "ready";
+        simTime = 0;
+        impactOccurred = false;
+        settledTimer = 0;
+        peakGForce = 0;
+        totalMomentumTransferred = 0;
+        cameraShake = 0;
+        cameraX = 0;
+        dustParticles = [];
+        skidMarks = [];
