+      // =========================================================================
+      // RIGID-BODY COLLISION DETECTION (2D SAT FOR OBB & CONVEX HULL)
+      // =========================================================================
+      function updateBrickTransform(b) {
+        b.cos = Math.cos(b.angle);
+        b.sin = Math.sin(b.angle);
+      }
+
+      function getBrickVertices(b) {
+        const wx = b.cos * b.hw;
+        const wy = b.sin * b.hw;
+        const hx = -b.sin * b.hh;
+        const hy = b.cos * b.hh;
+        return [
+          { x: b.x - wx - hx, y: b.y - wy - hy },
+          { x: b.x + wx - hx, y: b.y + wy - hy },
+          { x: b.x + wx + hx, y: b.y + wy + hy },
+          { x: b.x - wx + hx, y: b.y - wy + hy }
+        ];
+      }
+
+      // SAT between two brick OBBs A and B
+      function collideBrickBrick(a, b) {
+        const dx = b.x - a.x;
+        const dy = b.y - a.y;
+        // Bounding circle radius of 0.50x0.24 brick is sqrt(0.25^2 + 0.12^2) = 0.2773m
+        // Max center distance is 0.5546m -> distSq > 0.308
+        if (dx * dx + dy * dy > 0.308) return null;
+
+        const axesX = [a.cos, -a.sin, b.cos, -b.sin];
+        const axesY = [a.sin,  a.cos, b.sin,  b.cos];
+
+        let minOverlap = Infinity;
+        let bestAxisX = 0;
+        let bestAxisY = 0;
+
+        for (let i = 0; i < 4; i++) {
+          const ax = axesX[i];
+          const ay = axesY[i];
+
+          const rA = a.hw * Math.abs(ax * a.cos + ay * a.sin) +
+                     a.hh * Math.abs(-ax * a.sin + ay * a.cos);
+          const rB = b.hw * Math.abs(ax * b.cos + ay * b.sin) +
+                     b.hh * Math.abs(-ax * b.sin + ay * b.cos);
+
+          const dist = dx * ax + dy * ay;
+          const overlap = rA + rB - Math.abs(dist);
+          if (overlap <= 0) return null;
+
+          if (overlap < minOverlap) {
+            minOverlap = overlap;
+            if (dist < 0) {
+              bestAxisX = -ax;
+              bestAxisY = -ay;
+            } else {
+              bestAxisX = ax;
+              bestAxisY = ay;
+            }
+          }
+        }
+
+        // Find contact points (support vertices on B and A along contact normal)
+        const vertsA = getBrickVertices(a);
+        const vertsB = getBrickVertices(b);
+
+        // Collect vertices of B deepest along -normal and vertices of A deepest along +normal
+        let minProjB = Infinity;
+        for (let i = 0; i < 4; i++) {
+          const p = vertsB[i].x * bestAxisX + vertsB[i].y * bestAxisY;
+          if (p < minProjB) minProjB = p;
+        }
+        let maxProjA = -Infinity;
+        for (let i = 0; i < 4; i++) {
+          const p = vertsA[i].x * bestAxisX + vertsA[i].y * bestAxisY;
+          if (p > maxProjA) maxProjA = p;
+        }
+
+        const contacts = [];
+        const eps = 0.012;
+        for (let i = 0; i < 4; i++) {
+          const v = vertsB[i];
+          if (v.x * bestAxisX + v.y * bestAxisY <= minProjB + eps) {
+            if (pointInBrickMargin(v.x, v.y, a, 0.02)) {
+              contacts.push({ x: v.x, y: v.y });
+            }
+          }
+        }
+        for (let i = 0; i < 4; i++) {
+          const v = vertsA[i];
+          if (v.x * bestAxisX + v.y * bestAxisY >= maxProjA - eps) {
+            if (pointInBrickMargin(v.x, v.y, b, 0.02)) {
+              contacts.push({ x: v.x, y: v.y });
+            }
+          }
+        }
+
+        if (contacts.length === 0) {
+          // Fallback deepest vertex on B
+          let deepest = vertsB[0];
+          for (let i = 1; i < 4; i++) {
+            if (vertsB[i].x * bestAxisX + vertsB[i].y * bestAxisY <
+                deepest.x * bestAxisX + deepest.y * bestAxisY) {
+              deepest = vertsB[i];
+            }
+          }
+          contacts.push({ x: deepest.x, y: deepest.y });
+        } else if (contacts.length > 2) {
+          // Keep the two extreme points along the tangent for a stable 2-point manifold
+          const tx = -bestAxisY;
+          const ty = bestAxisX;
+          let minT = Infinity, maxT = -Infinity;
+          let pMin = contacts[0], pMax = contacts[0];
+          for (let i = 0; i < contacts.length; i++) {
+            const t = contacts[i].x * tx + contacts[i].y * ty;
+            if (t < minT) { minT = t; pMin = contacts[i]; }
+            if (t > maxT) { maxT = t; pMax = contacts[i]; }
+          }
+          contacts.length = 0;
+          contacts.push(pMin);
+          if (maxT - minT > 0.005) contacts.push(pMax);
+        }
+
+        return {
+          nx: bestAxisX,
+          ny: bestAxisY,
+          depth: minOverlap,
+          contacts: contacts
+        };
+      }
+
+      function pointInBrickMargin(px, py, b, margin) {
+        const dx = px - b.x;
+        const dy = py - b.y;
+        const lx = Math.abs(dx * b.cos + dy * b.sin);
+        const ly = Math.abs(-dx * b.sin + dy * b.cos);
+        return lx <= b.hw + margin && ly <= b.hh + margin;
+      }
+
+      // SAT between Car Convex Hull and Brick OBB
+      function collideCarBrick(c, carVerts, b) {
+        const dx = b.x - c.x;
+        const dy = b.y - c.y;
+        if (Math.abs(dx) > c.hw + 0.45 || Math.abs(dy) > c.hh + 0.45) return null;
+
+        const brickVerts = getBrickVertices(b);
+
+        let minOverlap = Infinity;
+        let bestNx = 0;
+        let bestNy = 0;
+
+        // Test Car polygon edge normals + Brick OBB axes
+        const numCarVerts = carVerts.length;
+        const totalAxes = numCarVerts + 2;
+
+        for (let i = 0; i < totalAxes; i++) {
+          let ax, ay;
+          if (i < numCarVerts) {
+            const p0 = carVerts[i];
+            const p1 = carVerts[(i + 1) % numCarVerts];
+            const ex = p1.x - p0.x;
+            const ey = p1.y - p0.y;
+            const len = Math.hypot(ex, ey);
+            if (len < 1e-6) continue;
+            ax = ey / len;
+            ay = -ex / len;
+          } else if (i === numCarVerts) {
+            ax = b.cos;
+            ay = b.sin;
+          } else {
+            ax = -b.sin;
+            ay = b.cos;
+          }
+
+          let minA = Infinity, maxA = -Infinity;
+          for (let j = 0; j < numCarVerts; j++) {
+            const proj = carVerts[j].x * ax + carVerts[j].y * ay;
+            if (proj < minA) minA = proj;
+            if (proj > maxA) maxA = proj;
+          }
+
+          let minB = Infinity, maxB = -Infinity;
+          for (let j = 0; j < 4; j++) {
+            const proj = brickVerts[j].x * ax + brickVerts[j].y * ay;
+            if (proj < minB) minB = proj;
+            if (proj > maxB) maxB = proj;
+          }
+
+          const overlap = Math.min(maxA, maxB) - Math.max(minA, minB);
+          if (overlap <= 0) return null;
+
+          if (overlap < minOverlap) {
+            minOverlap = overlap;
+            const centerDiff = dx * ax + dy * ay;
+            if (centerDiff < 0) {
+              bestNx = -ax;
+              bestNy = -ay;
+            } else {
+              bestNx = ax;
+              bestNy = ay;
+            }
+          }
+        }
+
+        // Contact point: average of deepest brick vertex(es) along -normal
+        let minProj = Infinity;
+        for (let i = 0; i < 4; i++) {
+          const p = brickVerts[i].x * bestNx + brickVerts[i].y * bestNy;
+          if (p < minProj) minProj = p;
+        }
+        let cx = 0, cy = 0, count = 0;
+        for (let i = 0; i < 4; i++) {
+          const p = brickVerts[i].x * bestNx + brickVerts[i].y * bestNy;
+          if (p <= minProj + 0.015) {
+            cx += brickVerts[i].x;
+            cy += brickVerts[i].y;
+            count++;
+          }
+        }
+        cx /= count;
+        cy /= count;
+
+        return {
+          nx: bestNx,
+          ny: bestNy,
+          depth: minOverlap,
+          cx: cx,
+          cy: cy
+        };
+      }
