+      // =========================================================================
+      // IMPULSE RESOLUTION
+      // =========================================================================
+      function resolveTwoBodyContact(a, b, cx, cy, nx, ny, depth, restitution, friction, isCarImpact) {
+        const rAx = cx - a.x;
+        const rAy = cy - a.y;
+        const rBx = cx - b.x;
+        const rBy = cy - b.y;
+
+        const vAx = a.vx - a.omega * rAy;
+        const vAy = a.vy + a.omega * rAx;
+        const vBx = b.vx - b.omega * rBy;
+        const vBy = b.vy + b.omega * rBx;
+
+        const rvx = vBx - vAx;
+        const rvy = vBy - vAy;
+
+        const velAlongNormal = rvx * nx + rvy * ny;
+
+        const rACrossN = rAx * ny - rAy * nx;
+        const rBCrossN = rBx * ny - rBy * nx;
+        const invMassSum = a.invMass + b.invMass +
+                           rACrossN * rACrossN * a.invInertia +
+                           rBCrossN * rBCrossN * b.invInertia;
+        if (invMassSum <= 0) return 0;
+
+        // Baumgarte stabilization bias
+        const slop = 0.0012;
+        const beta = isCarImpact ? 0.28 : 0.18;
+        const bias = Math.max(0, depth - slop) * (beta / SUB_DT);
+
+        let e = (-velAlongNormal > 0.65) ? restitution : 0;
+        let jn = (-(1 + e) * velAlongNormal + bias) / invMassSum;
+        if (jn < 0) jn = 0;
+
+        const impulseX = jn * nx;
+        const impulseY = jn * ny;
+
+        a.vx -= impulseX * a.invMass;
+        a.vy -= impulseY * a.invMass;
+        a.omega -= (rAx * impulseY - rAy * impulseX) * a.invInertia;
+
+        b.vx += impulseX * b.invMass;
+        b.vy += impulseY * b.invMass;
+        b.omega += (rBx * impulseY - rBy * impulseX) * b.invInertia;
+
+        // Recompute relative velocity for friction impulse
+        const vAx2 = a.vx - a.omega * rAy;
+        const vAy2 = a.vy + a.omega * rAx;
+        const vBx2 = b.vx - b.omega * rBy;
+        const vBy2 = b.vy + b.omega * rBx;
+        const rvx2 = vBx2 - vAx2;
+        const rvy2 = vBy2 - vAy2;
+
+        const tx = -ny;
+        const ty = nx;
+        const vt = rvx2 * tx + rvy2 * ty;
+
+        const rACrossT = rAx * ty - rAy * tx;
+        const rBCrossT = rBx * ty - rBy * tx;
+        const invMassTangent = a.invMass + b.invMass +
+                               rACrossT * rACrossT * a.invInertia +
+                               rBCrossT * rBCrossT * b.invInertia;
+
+        if (invMassTangent > 0) {
+          let jt = -vt / invMassTangent;
+          const maxFriction = jn * friction;
+          if (jt > maxFriction) jt = maxFriction;
+          if (jt < -maxFriction) jt = -maxFriction;
+
+          const fImpulseX = jt * tx;
+          const fImpulseY = jt * ty;
+
+          a.vx -= fImpulseX * a.invMass;
+          a.vy -= fImpulseY * a.invMass;
+          a.omega -= (rAx * fImpulseY - rAy * fImpulseX) * a.invInertia;
+
+          b.vx += fImpulseX * b.invMass;
+          b.vy += fImpulseY * b.invMass;
+          b.omega += (rBx * fImpulseY - rBy * fImpulseX) * b.invInertia;
+        }
+
+        return jn;
+      }
+
+      function resolveBrickGround(b) {
+        const verts = getBrickVertices(b);
+        const e = DEFAULTS.brickRestitution * 0.6;
+        const mu = DEFAULTS.groundFriction;
+
+        for (let i = 0; i < 4; i++) {
+          const v = verts[i];
+          if (v.y < 0) {
+            const depth = -v.y;
+            const rx = v.x - b.x;
+            const ry = v.y - b.y;
+
+            const vx = b.vx - b.omega * ry;
+            const vy = b.vy + b.omega * rx;
+
+            const rCrossN = rx; // normal is (0, 1)
+            const kN = b.invMass + rCrossN * rCrossN * b.invInertia;
+            const slop = 0.0008;
+            const bias = Math.max(0, depth - slop) * (0.22 / SUB_DT);
+
+            const effE = (-vy > 0.8) ? e : 0;
+            let jn = (-(1 + effE) * vy + bias) / kN;
+            if (jn > 0) {
+              b.vy += jn * b.invMass;
+              b.omega += rx * jn * b.invInertia;
+
+              // Ground friction along tangent (1, 0)
+              const vx2 = b.vx - b.omega * ry;
+              const rCrossT = -ry;
+              const kT = b.invMass + rCrossT * rCrossT * b.invInertia;
+              let jt = -vx2 / kT;
+              const maxF = jn * mu;
+              if (jt > maxF) jt = maxF;
+              if (jt < -maxF) jt = -maxF;
+
+              b.vx += jt * b.invMass;
+              b.omega += (-ry * jt) * b.invInertia;
+            }
+          }
+        }
+      }
+
+      // =========================================================================
+      // MORTAR & INTER-LAYER COHESION SOLVER
+      // =========================================================================
+      function solveMortarCohesion() {
+        // Scale mortar fracture strength naturally with brick mass so heavier masonry has realistic bond capacity
+        const massScale = Math.pow(settings.brickMass / 2.5, 0.85);
+        const maxStretch = 0.0085;
+        const maxAngleDiff = 0.045;
+        const maxImpulse = 4.2 * massScale;
+
+        for (let i = 0; i < mortarJoints.length; i++) {
+          const j = mortarJoints[i];
+          if (j.broken) continue;
+
+          const a = j.a;
+          const b = j.b;
+
+          const angleDiff = Math.abs(b.angle - a.angle);
+          const avgAngle = (a.angle + b.angle) * 0.5;
+          const cos = Math.cos(avgAngle);
+          const sin = Math.sin(avgAngle);
+
+          const targetDx = j.dx0 * cos - j.dy0 * sin;
+          const targetDy = j.dx0 * sin + j.dy0 * cos;
+
+          const errX = (b.x - a.x) - targetDx;
+          const errY = (b.y - a.y) - targetDy;
+          const errDist = Math.hypot(errX, errY);
+
+          if (errDist > maxStretch * j.strength || angleDiff > maxAngleDiff * j.strength) {
+            breakJoint(j, (a.x + b.x) * 0.5, (a.y + b.y) * 0.5);
+            continue;
+          }
+
+          // Relative velocity damping + positional spring impulse
+          const rvx = b.vx - a.vx;
+          const rvy = b.vy - a.vy;
+          const kStiff = 18.0;
+          const damp = 0.45;
+
+          const jx = (errX * kStiff + rvx * damp) * a.mass;
+          const jy = (errY * kStiff + rvy * damp) * a.mass;
+          const jMag = Math.hypot(jx, jy);
+
+          if (jMag > maxImpulse * j.strength) {
+            breakJoint(j, (a.x + b.x) * 0.5, (a.y + b.y) * 0.5);
+            continue;
+          }
+
+          a.vx += jx * a.invMass;
+          a.vy += jy * a.invMass;
+          b.vx -= jx * b.invMass;
+          b.vy -= jy * b.invMass;
+
+          const rotCorr = (b.angle - a.angle) * 0.25 + (b.omega - a.omega) * 0.35;
+          a.omega += rotCorr;
+          b.omega -= rotCorr;
+        }
+
+        // Depth layer collar-joint couplings (transfers momentum between overlapping wythes)
+        const maxDepthStretch = 0.028;
+        const maxDepthImpulse = 5.5 * massScale;
+        for (let i = 0; i < depthCouplings.length; i++) {
+          const d = depthCouplings[i];
+          if (d.broken) continue;
+
+          const a = d.a;
+          const b = d.b;
+          const errX = (b.x - a.x) - d.dx0;
+          const errY = (b.y - a.y) - d.dy0;
+          const dist = Math.hypot(errX, errY);
+
+          if (dist > maxDepthStretch || Math.abs(b.angle - a.angle) > 0.12) {
+            d.broken = true;
+            a.brokenBonds++;
+            b.brokenBonds++;
+            continue;
+          }
+
+          const rvx = b.vx - a.vx;
+          const rvy = b.vy - a.vy;
+          const jx = (errX * 12.0 + rvx * 0.38) * a.mass;
+          const jy = (errY * 12.0 + rvy * 0.38) * a.mass;
+
+          if (Math.hypot(jx, jy) > maxDepthImpulse) {
+            d.broken = true;
+            a.brokenBonds++;
+            b.brokenBonds++;
+            continue;
+          }
+
+          a.vx += jx * a.invMass;
+          a.vy += jy * a.invMass;
+          b.vx -= jx * b.invMass;
+          b.vy -= jy * b.invMass;
+        }
+      }
+
+      function breakJoint(j, wx, wy) {
+        j.broken = true;
+        j.a.brokenBonds++;
+        j.b.brokenBonds++;
+        j.a.sleeping = false;
+        j.b.sleeping = false;
+        j.a.sleepTimer = 0;
+        j.b.sleepTimer = 0;
+
+        // Spawn deterministic visual mortar dust puff
+        if (dustParticles.length < 280 && nextVisualRand() < 0.45) {
+          spawnDust(wx, wy, 2);
+        }
+      }
+
+      function spawnDust(wx, wy, count) {
+        for (let i = 0; i < count; i++) {
+          const ang = nextVisualRand() * Math.PI * 2;
+          const spd = 0.4 + nextVisualRand() * 3.2;
+          const isChip = nextVisualRand() < 0.35;
+          dustParticles.push({
+            x: wx + (nextVisualRand() - 0.5) * 0.14,
+            y: Math.max(0.03, wy + (nextVisualRand() - 0.5) * 0.14),
+            vx: Math.cos(ang) * spd + (car ? car.vx * 0.18 : 0),
+            vy: Math.abs(Math.sin(ang)) * spd + 0.5,
+            size: isChip ? (2.5 + nextVisualRand() * 3.5) : (8 + nextVisualRand() * 14),
+            alpha: isChip ? 0.9 : 0.42,
+            life: 0,
+            maxLife: isChip ? (0.45 + nextVisualRand() * 0.5) : (0.55 + nextVisualRand() * 0.65),
+            isChip: isChip
+          });
+        }
+      }
+
+      // =========================================================================
+      // PHYSICS STEP (SUB-STEPPED DETERMINISTIC SOLVER)
+      // =========================================================================
+      function stepPhysics() {
+        if (simState !== "running") return;
+
+        const g = DEFAULTS.gravity;
+        const groundMu = DEFAULTS.groundFriction;
+        const brickMu = DEFAULTS.brickFriction;
+        const brickRest = DEFAULTS.brickRestitution;
+
+        for (let sub = 0; sub < SUBSTEPS; sub++) {
+          simTime += SUB_DT;
+          car.prevVx = car.vx;
+
+          // 1. Update Car Integration & Suspension
+          if (!impactOccurred) {
+            // Maintain exact configured test speed on approach track until impact
+            car.vx = settings.carSpeed;
+            car.vy = 0;
+            car.angle = 0;
+            car.omega = 0;
+          } else {
+            // Post-impact: gravity + two-axle spring-damper suspension + ground braking friction
+            car.vy -= g * SUB_DT;
+
+            const restY = car.hh;
+            const yErr = restY - car.y;
+            // Suspension vertical spring + damper
+            const kSpring = 48.0;
+            const cDamp = 11.5;
+            if (car.y <= restY + 0.08) {
+              car.vy += (yErr * kSpring - car.vy * cDamp) * SUB_DT;
+            }
+
+            // Pitch suspension restoring torque (front & rear axles resist pitch)
+            const kPitch = 65.0;
+            const cPitch = 12.0;
+            car.omega += (-car.angle * kPitch - car.omega * cPitch) * SUB_DT;
+            car.angle = Math.max(-0.22, Math.min(0.22, car.angle));
+
+            // Ground tire/chassis friction when in contact with ground
+            if (car.y <= restY + 0.04) {
+              const decel = groundMu * g * SUB_DT;
+              if (Math.abs(car.vx) <= decel) {
+                car.vx = 0;
+              } else {
+                car.vx -= Math.sign(car.vx) * decel;
+              }
+
+              // Record skid marks during heavy post-impact braking/deceleration
+              if (Math.abs(car.vx) > 0.8 && sub === 0 && skidMarks.length < 300) {
+                skidMarks.push({
+                  x: car.x - 1.25,
+                  w: Math.max(0.15, Math.abs(car.vx) * FIXED_DT * 1.1),
+                  alpha: Math.min(0.55, Math.abs(car.vx) / 25)
+                });
+                skidMarks.push({
+                  x: car.x + 1.20,
+                  w: Math.max(0.15, Math.abs(car.vx) * FIXED_DT * 1.1),
+                  alpha: Math.min(0.55, Math.abs(car.vx) / 25)
+                });
+              }
+            }
+          }
+
+          car.x += car.vx * SUB_DT;
+          car.y += car.vy * SUB_DT;
+          car.angle += car.omega * SUB_DT;
+
+          // Clamp car above ground plane
+          if (car.y < car.hh) {
+            car.y = car.hh;
+            if (car.vy < 0) car.vy = -car.vy * 0.12;
+          }
+
+          const wheelRadius = 0.34;
+          car.wheelAngle += (car.vx * SUB_DT) / wheelRadius;
+
+          // Check if car has reached the wall proximity to wake physics
+          const wallFrontTriggerX = TRACK_START_X + DEFAULTS.carWidth + RUNWAY_GAP - 0.08;
+          if (!impactOccurred && (car.x + car.hw) >= wallFrontTriggerX) {
+            impactOccurred = true;
+          }
+
+          // 2. Integrate Bricks (only once impact begins so wall is 100% motionless before impact)
+          if (impactOccurred) {
+            for (let i = 0; i < bricks.length; i++) {
+              const b = bricks[i];
+              if (b.sleeping) continue;
+
+              b.vy -= g * SUB_DT;
+
+              // Mild aerodynamic drag & angular damping for physical stability at high speeds
+              b.vx *= 0.9994;
+              b.vy *= 0.9994;
+              b.omega *= 0.996;
+
+              b.x += b.vx * SUB_DT;
+              b.y += b.vy * SUB_DT;
+              b.angle += b.omega * SUB_DT;
+              updateBrickTransform(b);
+            }
+
+            // 3. Solve Mortar Cohesion & Inter-Layer Couplings
+            solveMortarCohesion();
+
+            // 4. Collect Contact Manifolds for Current Substep
+            const carVerts = getCarHullVertices(car);
+            const carContacts = [];
+            for (let i = 0; i < bricks.length; i++) {
+              const b = bricks[i];
+              const m = collideCarBrick(car, carVerts, b);
+              if (m) {
+                b.sleeping = false;
+                b.sleepTimer = 0;
+                carContacts.push({ brick: b, m: m });
+              }
+            }
+
+            const brickContacts = [];
+            for (let l = 0; l < bricksByLayer.length; l++) {
+              const layerBricks = bricksByLayer[l];
+              const n = layerBricks.length;
+              for (let i = 0; i < n; i++) {
+                const bA = layerBricks[i];
+                for (let j = i + 1; j < n; j++) {
+                  const bB = layerBricks[j];
+                  if (bA.sleeping && bB.sleeping) continue;
+                  if (Math.abs(bB.x - bA.x) > 0.56 || Math.abs(bB.y - bA.y) > 0.56) continue;
+                  const m = collideBrickBrick(bA, bB);
+                  if (m) {
+                    if (!bA.sleeping || !bB.sleeping) {
+                      bA.sleeping = false;
+                      bB.sleeping = false;
+                    }
+                    brickContacts.push({ a: bA, b: bB, m: m });
+                  }
+                }
+              }
+            }
+
+            // 5. Iterative Sequential Impulse Solver
+            let substepCarImpulse = 0;
+            for (let iter = 0; iter < SOLVER_ITERATIONS; iter++) {
+              // Ground contacts first
+              for (let i = 0; i < bricks.length; i++) {
+                const b = bricks[i];
+                if (!b.sleeping && b.y < 0.32) {
+                  resolveBrickGround(b);
+                }
+              }
+
+              // Alternate sweep order for symmetric force propagation across columns
+              if (iter % 2 === 0) {
+                for (let i = 0; i < brickContacts.length; i++) {
+                  const c = brickContacts[i];
+                  const pts = c.m.contacts;
+                  for (let k = 0; k < pts.length; k++) {
+                    resolveTwoBodyContact(
+                      c.a, c.b,
+                      pts[k].x, pts[k].y,
+                      c.m.nx, c.m.ny,
+                      c.m.depth / pts.length,
+                      brickRest, brickMu, false
+                    );
+                  }
+                }
+              } else {
+                for (let i = brickContacts.length - 1; i >= 0; i--) {
+                  const c = brickContacts[i];
+                  const pts = c.m.contacts;
+                  for (let k = 0; k < pts.length; k++) {
+                    resolveTwoBodyContact(
+                      c.a, c.b,
+                      pts[k].x, pts[k].y,
+                      c.m.nx, c.m.ny,
+                      c.m.depth / pts.length,
+                      brickRest, brickMu, false
+                    );
+                  }
+                }
+              }
+
+              // Car-Brick contacts
+              for (let i = 0; i < carContacts.length; i++) {
+                const cc = carContacts[i];
+                const jn = resolveTwoBodyContact(
+                  car, cc.brick,
+                  cc.m.cx, cc.m.cy,
+                  cc.m.nx, cc.m.ny,
+                  cc.m.depth,
+                  brickRest, brickMu * 0.75, true
+                );
+                substepCarImpulse += jn;
+              }
+            }
+
+            // Track impact telemetry, front crumple deformation, airbag & camera shake
+            if (substepCarImpulse > 0) {
+              totalMomentumTransferred += substepCarImpulse;
+              const instAccelG = Math.abs(car.vx - car.prevVx) / (SUB_DT * g);
+              if (instAccelG > peakGForce) peakGForce = instAccelG;
+
+              // Progressive front crumple zone compression
+              const crumpleDelta = Math.min(0.015, substepCarImpulse / 420000);
+              car.crumple = Math.min(0.36, car.crumple + crumpleDelta);
+
+              if (substepCarImpulse > 900 && !car.airbagDeployed) {
+                car.airbagDeployed = true;
+                car.dummyPitchVel = 7.5;
+              }
+
+              if (substepCarImpulse > 1800) {
+                cameraShake = Math.min(10, cameraShake + substepCarImpulse / 8500);
+                if (dustParticles.length < 280 && nextVisualRand() < 0.6) {
+                  spawnDust(car.x + car.hw - car.crumple, car.y - 0.1, 2);
+                }
+              }
+            }
+
+            // 6. Nonlinear Position Projection (prevents overlap and tunneling)
+            for (let pass = 0; pass < 3; pass++) {
+              // Brick-Brick overlap projection
+              for (let i = 0; i < brickContacts.length; i++) {
+                const c = brickContacts[i];
+                const a = c.a;
+                const b = c.b;
+                const m = collideBrickBrick(a, b);
+                if (m && m.depth > 0.0015) {
+                  const corr = (m.depth - 0.001) * 0.42;
+                  const totalInv = a.invMass + b.invMass;
+                  const shareA = a.invMass / totalInv;
+                  const shareB = b.invMass / totalInv;
+                  a.x -= m.nx * corr * shareA;
+                  a.y -= m.ny * corr * shareA;
+                  b.x += m.nx * corr * shareB;
+                  b.y += m.ny * corr * shareB;
+                }
+              }
+
+              // Car-Brick overlap projection
+              const updatedCarVerts = getCarHullVertices(car);
+              for (let i = 0; i < bricks.length; i++) {
+                const b = bricks[i];
+                const m = collideCarBrick(car, updatedCarVerts, b);
+                if (m && m.depth > 0.001) {
+                  const corr = (m.depth - 0.0005) * 0.78;
+                  const totalInv = car.invMass + b.invMass;
+                  const carShare = car.invMass / totalInv;
+                  const brickShare = b.invMass / totalInv;
+                  car.x -= m.nx * corr * carShare;
+                  car.y -= Math.max(0, m.ny * corr * carShare);
+                  b.x += m.nx * corr * brickShare;
+                  b.y += m.ny * corr * brickShare;
+                }
+              }
+
+              // Ground clamp for all bricks
+              for (let i = 0; i < bricks.length; i++) {
+                const b = bricks[i];
+                if (b.y < 0.30) {
+                  updateBrickTransform(b);
+                  const minY = b.y - (Math.abs(b.sin) * b.hw + Math.abs(b.cos) * b.hh);
+                  if (minY < 0) {
+                    b.y -= minY;
+                    if (b.vy < 0) b.vy = 0;
+                    // Extra rolling friction when flat/near-flat on the ground
+                    b.vx *= 0.985;
+                    b.omega *= 0.94;
+                  }
+                }
+              }
+            }
+          }
+
+          // Update crash-test dummy head/torso spring inside cabin
+          car.dummyPitch += car.dummyPitchVel * SUB_DT;
+          car.dummyPitchVel += (-car.dummyPitch * 45 - car.dummyPitchVel * 6.5) * SUB_DT;
+          car.dummyPitch = Math.max(-0.25, Math.min(0.65, car.dummyPitch));
+        }
+
+        // Post-frame sleep stabilization & settling detection
+        let movingCount = 0;
+        if (impactOccurred) {
+          for (let i = 0; i < bricks.length; i++) {
+            const b = bricks[i];
+            if (b.sleeping) continue;
+
+            const speedSq = b.vx * b.vx + b.vy * b.vy;
+            const angSpeed = Math.abs(b.omega);
+
+            // Check if brick is moving perceptibly
+            if (speedSq > 0.0036 || angSpeed > 0.10) {
+              movingCount++;
+              b.sleepTimer = 0;
+            } else {
+              b.sleepTimer += FIXED_DT;
+              // Gently damp micro-oscillations once nearly at rest
+              b.vx *= 0.82;
+              b.vy *= 0.82;
+              b.omega *= 0.78;
+              if (b.sleepTimer > 0.38) {
+                b.vx = 0;
+                b.vy = 0;
+                b.omega = 0;
+                b.sleeping = true;
+              }
+            }
+          }
+
+          const carMoving = Math.abs(car.vx) > 0.05 || Math.abs(car.vy) > 0.05;
+          if (movingCount === 0 && !carMoving && simTime > 0.6) {
+            settledTimer += FIXED_DT;
+            if (settledTimer > 0.45) {
+              car.vx = 0;
+              car.vy = 0;
+              car.omega = 0;
+              simState = "settled";
+              updateStatusUI("settled");
+            }
+          } else {
+            settledTimer = 0;
+          }
+        }
+
+        // Update visual particles
+        for (let i = dustParticles.length - 1; i >= 0; i--) {
+          const p = dustParticles[i];
+          p.life += FIXED_DT;
+          if (p.life >= p.maxLife) {
+            dustParticles.splice(i, 1);
+            continue;
+          }
+          p.x += p.vx * FIXED_DT;
+          p.y += p.vy * FIXED_DT;
+          if (p.isChip) {
+            p.vy -= g * FIXED_DT;
+            if (p.y < 0.02) {
+              p.y = 0.02;
+              p.vy = -p.vy * 0.3;
+              p.vx *= 0.7;
+            }
+          } else {
+            p.vx *= 0.95;
+            p.vy += 0.35 * FIXED_DT;
+            p.size += 12 * FIXED_DT;
+          }
+        }
+
+        cameraShake *= 0.86;
+        if (cameraShake < 0.1) cameraShake = 0;
+
+        updateTelemetryUI();
+      }
+
+      // =========================================================================
+      // TELEMETRY & UI UPDATES
+      // =========================================================================
+      function getMovingBricksCount() {
+        if (!impactOccurred) return 0;
+        let count = 0;
+        for (let i = 0; i < bricks.length; i++) {
+          const b = bricks[i];
+          if (!b.sleeping && (b.vx * b.vx + b.vy * b.vy > 0.0036 || Math.abs(b.omega) > 0.10)) {
+            count++;
+          }
+        }
+        return count;
+      }
+
+      function getDisplacedBricksCount() {
+        let count = 0;
+        for (let i = 0; i < bricks.length; i++) {
+          const b = bricks[i];
+          const dx = b.x - b.initialX;
+          const dy = b.y - b.initialY;
+          if (dx * dx + dy * dy > 0.0025 || Math.abs(b.angle) > 0.06) {
+            count++;
+          }
+        }
+        return count;
+      }
+
+      function updateStatusUI(state) {
+        statusPill.className = "status-pill";
+        if (state === "running") {
+          statusPill.classList.add("running");
+          statusText.textContent = "Testing";
+        } else if (state === "settled") {
+          statusPill.classList.add("settled");
+          statusText.textContent = "Settled";
+        } else {
+          statusText.textContent = "Ready";
+        }
+      }
+
+      function updateTelemetryUI() {
+        const displaySpeed = simState === "ready" ? settings.carSpeed : Math.abs(car.vx);
+        const kmh = Math.round(displaySpeed * 3.6);
+        telSpeed.textContent = displaySpeed.toFixed(1);
+        telSpeedKmh.textContent = "m/s (" + kmh + " km/h)";
+
+        telTime.textContent = simTime.toFixed(2);
+
+        const totalBricks = bricks.length;
+        const movingCount = getMovingBricksCount();
+        const displacedCount = getDisplacedBricksCount();
+        const displacedPct = totalBricks > 0 ? Math.round((displacedCount / totalBricks) * 100) : 0;
+
+        telMoving.textContent = String(movingCount);
+        telTotalBricks.textContent = "/ " + totalBricks;
+
+        telDisplaced.textContent = String(displacedCount);
+        telDisplacedPct.textContent = "(" + displacedPct + "%)";
+
+        const totalWallMass = totalBricks * settings.brickMass;
+        telWallMass.textContent = totalWallMass.toFixed(1);
+
+        telPeakG.textContent = peakGForce.toFixed(1) + " G";
+        telImpulse.textContent = (totalMomentumTransferred / 1000).toFixed(1) + " kN\u00B7s";
+      }
+
+      function syncSettingsLabels() {
+        valCarSpeed.textContent = settings.carSpeed + " m/s";
+        valWallCols.textContent = settings.wallColumns + " bricks";
+        valWallRows.textContent = settings.wallRows + " bricks";
+        valWallLayers.textContent = settings.wallDepthLayers + (settings.wallDepthLayers === 1 ? " layer" : " layers");
+        valBrickMass.textContent = settings.brickMass.toFixed(1) + " kg";
+      }
+
+      // =========================================================================
+      // RENDERING (80 PIXELS PER METER BASELINE SCALE)
+      // =========================================================================
+      function resizeCanvas() {
+        const dpr = window.devicePixelRatio || 1;
+        const rect = stage.getBoundingClientRect();
+        canvas.width = Math.max(1, Math.floor(rect.width * dpr));
+        canvas.height = Math.max(1, Math.floor(rect.height * dpr));
+      }
+
+      function renderScene() {
+        const dpr = window.devicePixelRatio || 1;
+        const cw = canvas.width / dpr;
+        const ch = canvas.height / dpr;
+
+        ctx.save();
+        ctx.scale(dpr, dpr);
+
+        // Compute effective scale (80 px/m baseline, gently scaled only if viewport is smaller than initial scene)
+        const baseScale = DEFAULTS.scale;
+        const wallFrontX = TRACK_START_X + DEFAULTS.carWidth + RUNWAY_GAP;
+        const wallWidthM = settings.wallColumns * DEFAULTS.brickWidth + 0.5;
+        const minVisibleWidthM = wallFrontX + wallWidthM + 1.4;
+        const fitScaleX = cw / Math.max(15.2, minVisibleWidthM);
+        const scale = Math.min(baseScale, fitScaleX);
+
+        // Smooth camera pan if high-speed car travels beyond initial right edge
+        const maxVisibleX = cw / scale;
+        let targetCamX = 0;
+        if (simState !== "ready" && car.x + 5.0 > maxVisibleX) {
+          targetCamX = Math.min(10.0, (car.x + 5.0) - maxVisibleX);
+        }
+        cameraX += (targetCamX - cameraX) * 0.08;
+
+        const groundScreenY = ch - Math.max(64, ch * 0.15);
+
+        // Apply deterministic screen-space impact shake
+        let shakeDx = 0;
+        let shakeDy = 0;
+        if (cameraShake > 0.1) {
+          shakeDx = Math.sin(simTime * 95) * cameraShake;
+          shakeDy = Math.cos(simTime * 115) * cameraShake * 0.7;
+        }
+
+        // 1. Background Sky & Test Facility Backdrop
+        const skyGrad = ctx.createLinearGradient(0, 0, 0, groundScreenY);
+        skyGrad.addColorStop(0, "#0b111e");
+        skyGrad.addColorStop(0.65, "#131c2e");
+        skyGrad.addColorStop(1, "#1c283d");
+        ctx.fillStyle = skyGrad;
+        ctx.fillRect(0, 0, cw, groundScreenY);
+
+        ctx.save();
+        ctx.translate(shakeDx - cameraX * scale, shakeDy);
+
+        // Photogrammetry Background Calibration Grid (1m and 0.5m world grid)
+        drawCalibrationGrid(scale, groundScreenY, cw / scale + cameraX + 4);
+
+        // 2. Ground Plane, Sub-base & Asphalt Test Track
+        drawGroundAndTrack(scale, groundScreenY, cw / scale + cameraX + 6);
+
+        // 3. Tire Skid Marks
+        drawSkidMarks(scale, groundScreenY);
+
+        // 4. Staggered Physical Brick Wall (back depth layers to front layer)
+        drawBricks(scale, groundScreenY);
+
+        // 5. Test Vehicle (Car Body, Cabin, Crash Dummy, Wheels, Fiducial Targets)
+        drawCar(scale, groundScreenY);
+
+        // 6. Impact Dust & Mortar Chips
+        drawDustParticles(scale, groundScreenY);
+
+        ctx.restore();
+        ctx.restore();
+      }
+
+      function drawCalibrationGrid(scale, groundY, maxWorldX) {
+        // Subtle 1-meter engineering grid lines
+        ctx.strokeStyle = "rgba(148, 163, 184, 0.055)";
+        ctx.lineWidth = 1;
+        ctx.beginPath();
+        for (let m = 0; m <= maxWorldX; m += 1) {
+          const x = m * scale;
+          ctx.moveTo(x, 0);
+          ctx.lineTo(x, groundY);
+        }
+        for (let m = 1; m <= 8; m += 1) {
+          const y = groundY - m * scale;
+          if (y < 0) break;
+          ctx.moveTo(0, y);
+          ctx.lineTo(maxWorldX * scale, y);
+        }
+        ctx.stroke();
+
+        // Crash test facility photogrammetry backdrop wall & height scale near impact zone
+        const wallFrontX = TRACK_START_X + DEFAULTS.carWidth + RUNWAY_GAP;
+        const rulerX = (wallFrontX - 0.55) * scale;
+        ctx.strokeStyle = "rgba(56, 189, 248, 0.28)";
+        ctx.lineWidth = 1;
+        ctx.beginPath();
+        ctx.moveTo(rulerX, groundY);
+        ctx.lineTo(rulerX, groundY - 4.0 * scale);
+        ctx.stroke();
+
+        ctx.fillStyle = "rgba(148, 163, 184, 0.55)";
+        ctx.font = "600 10px " + getComputedStyle(document.body).getPropertyValue("--font-mono");
+        ctx.textAlign = "right";
+        for (let h = 1; h <= 4; h++) {
+          const py = groundY - h * scale;
+          if (py > 14) {
+            ctx.fillRect(rulerX - 5, py, 5, 1);
+            ctx.fillText(h + ".0m", rulerX - 8, py + 3);
+          }
+        }
+
+        // Impact plane marker line
+        const impactLineX = wallFrontX * scale;
+        ctx.save();
+        ctx.setLineDash([4, 4]);
+        ctx.strokeStyle = "rgba(249, 115, 22, 0.35)";
+        ctx.beginPath();
+        ctx.moveTo(impactLineX, groundY);
+        ctx.lineTo(impactLineX, groundY - 3.2 * scale);
+        ctx.stroke();
+        ctx.restore();
+      }
+
+      function drawGroundAndTrack(scale, groundY, maxWorldX) {
+        const trackEndPx = maxWorldX * scale;
+
+        // Deep soil / concrete sub-grade
+        const groundGrad = ctx.createLinearGradient(0, groundY, 0, groundY + 120);
+        groundGrad.addColorStop(0, "#1e293b");
+        groundGrad.addColorStop(0.18, "#0f172a");
+        groundGrad.addColorStop(1, "#060911");
+        ctx.fillStyle = groundGrad;
+        ctx.fillRect(0, groundY, trackEndPx, 160);
+
+        // Asphalt surface strip
+        ctx.fillStyle = "#334155";
+        ctx.fillRect(0, groundY, trackEndPx, 8);
+
+        // High-visibility crash test curb stripes every 1.0 meter
+        for (let m = 0; m < maxWorldX; m++) {
+          ctx.fillStyle = (m % 2 === 0) ? "#cbd5e1" : "#475569";
+          ctx.fillRect(m * scale, groundY + 8, scale, 4);
+        }
+
+        // Top surface crisp horizon line
+        ctx.strokeStyle = "#94a3b8";
+        ctx.lineWidth = 1.5;
+        ctx.beginPath();
+        ctx.moveTo(0, groundY);
+        ctx.lineTo(trackEndPx, groundY);
+        ctx.stroke();
+
+        // Distance markers in meters along the track
+        ctx.fillStyle = "#94a3b8";
+        ctx.font = "600 10px monospace";
+        ctx.textAlign = "center";
+        for (let m = 0; m <= maxWorldX; m++) {
+          const x = m * scale;
+          const isMajor = (m % 5 === 0);
+          ctx.strokeStyle = isMajor ? "rgba(248, 250, 252, 0.55)" : "rgba(148, 163, 184, 0.25)";
+          ctx.beginPath();
+          ctx.moveTo(x, groundY + 12);
+          ctx.lineTo(x, groundY + (isMajor ? 22 : 17));
+          ctx.stroke();
+
+          if (isMajor || m === Math.round(TRACK_START_X + DEFAULTS.carWidth + RUNWAY_GAP)) {
+            ctx.fillText(m + "m", x, groundY + 34);
+          }
+        }
+      }
+
+      function drawSkidMarks(scale, groundY) {
+        if (skidMarks.length === 0) return;
+        for (let i = 0; i < skidMarks.length; i++) {
+          const s = skidMarks[i];
+          ctx.fillStyle = "rgba(15, 23, 42, " + s.alpha.toFixed(2) + ")";
+          ctx.fillRect(s.x * scale, groundY - 1.5, s.w * scale, 4);
+        }
+      }
+
+      function drawBricks(scale, groundY) {
+        const layers = settings.wallDepthLayers;
+
+        // Render from backmost depth layer (layers - 1) to frontmost layer (0)
+        for (let l = layers - 1; l >= 0; l--) {
+          const layerBricks = bricksByLayer[l];
+          if (!layerBricks) continue;
+
+          // Subtle 2.5D depth projection offset for back layers so overlapping wythes are clearly visible
+          const depthPxX = l * 4.5;
+          const depthPxY = -l * 3.5;
+          const layerDarken = l * 0.14;
+
+          for (let i = 0; i < layerBricks.length; i++) {
+            const b = layerBricks[i];
+            const px = b.x * scale + depthPxX;
+            const py = groundY - b.y * scale + depthPxY;
+            const pw = b.w * scale;
+            const ph = b.h * scale;
+
+            ctx.save();
+            ctx.translate(px, py);
+            ctx.rotate(-b.angle);
+
+            // Terracotta brick palette with deterministic variation & depth shading
+            const baseR = Math.round((196 - b.shade * 26) * (1 - layerDarken));
+            const baseG = Math.round((78 - b.shade * 16) * (1 - layerDarken));
+            const baseB = Math.round((52 - b.shade * 12) * (1 - layerDarken));
+
+            // Mortar bed border / outer brick body
+            ctx.fillStyle = "rgb(" + baseR + "," + baseG + "," + baseB + ")";
+            ctx.strokeStyle = (l === 0) ? "rgba(226, 232, 240, 0.68)" : "rgba(148, 163, 184, 0.38)";
+            ctx.lineWidth = 1.1;
+
+            ctx.beginPath();
+            ctx.rect(-pw * 0.5, -ph * 0.5, pw, ph);
+            ctx.fill();
+            ctx.stroke();
+
+            // Inner brick bevel highlight
+            ctx.fillStyle = "rgba(255, 255, 255, 0.08)";
+            ctx.fillRect(-pw * 0.5 + 1.5, -ph * 0.5 + 1.5, pw - 3, 2.5);
+
+            // Subtle masonry frog / core indentation detail
+            ctx.fillStyle = "rgba(0, 0, 0, 0.16)";
+            ctx.fillRect(-pw * 0.28, -ph * 0.16, pw * 0.56, ph * 0.32);
+
+            ctx.restore();
+          }
+        }
+      }
+
+      function drawCar(scale, groundY) {
+        if (!car) return;
+
+        const px = car.x * scale;
+        const py = groundY - car.y * scale;
+        const hw = car.hw * scale;
+        const hh = car.hh * scale;
+        const crumplePx = car.crumple * scale;
+
+        ctx.save();
+        ctx.translate(px, py);
+        ctx.rotate(-car.angle);
+
+        // Ground shadow beneath car
+        ctx.fillStyle = "rgba(0, 0, 0, 0.42)";
+        ctx.beginPath();
+        ctx.ellipse(0, hh - 2, hw * 0.92, 6, 0, 0, Math.PI * 2);
+        ctx.fill();
+
+        const frontX = hw - crumplePx;
+        const hoodBuckleY = -crumplePx * 0.22;
+
+        // 1. Main Vehicle Chassis Silhouette (4.2m wide x 1.45m tall)
+        const bodyGrad = ctx.createLinearGradient(0, -hh, 0, hh);
+        bodyGrad.addColorStop(0, "#fb923c");
+        bodyGrad.addColorStop(0.45, "#f97316");
+        bodyGrad.addColorStop(0.85, "#c2410c");
+        bodyGrad.addColorStop(1, "#7c2d12");
+
+        ctx.fillStyle = bodyGrad;
+        ctx.strokeStyle = "#fed7aa";
+        ctx.lineWidth = 1.4;
+
+        ctx.beginPath();
+        ctx.moveTo(-hw, hh - 10);                         // rear lower bumper
+        ctx.lineTo(frontX - 6, hh - 8);                   // underbody sill
+        ctx.lineTo(frontX, hh - 20);                      // front air dam / bumper nose
+        ctx.lineTo(frontX - 3, hh - 64 + hoodBuckleY);    // front grille top
+        ctx.lineTo(hw * 0.44, hh - 68 + hoodBuckleY * 1.4); // hood buckle / cowl
+        ctx.lineTo(hw * 0.34, -hh + 4);                   // windshield header / roof front
+        ctx.lineTo(-hw * 0.46, -hh + 4);                  // roof rear
+        ctx.lineTo(-hw * 0.78, hh - 66);                  // rear window base / C-pillar
+        ctx.lineTo(-hw, hh - 60);                         // trunk deck
+        ctx.closePath();
+        ctx.fill();
+        ctx.stroke();
+
+        // Dark lower rocker panel & bumpers
+        ctx.fillStyle = "#1e293b";
+        ctx.fillRect(-hw, hh - 16, hw + frontX - 2, 9);
+
+        // 2. Cabin Greenhouse (Windows, B-Pillar, Crash-Test Dummy & Airbag)
+        ctx.save();
+        ctx.beginPath();
+        ctx.moveTo(hw * 0.40, hh - 65);
+        ctx.lineTo(hw * 0.31, -hh + 10);
+        ctx.lineTo(-hw * 0.43, -hh + 10);
+        ctx.lineTo(-hw * 0.72, hh - 64);
+        ctx.closePath();
+        ctx.fillStyle = "#0f172a";
+        ctx.fill();
+        ctx.clip();
+
+        // Tinted window reflection
+        const winGrad = ctx.createLinearGradient(0, -hh, 0, hh - 60);
+        winGrad.addColorStop(0, "rgba(56, 189, 248, 0.25)");
+        winGrad.addColorStop(1, "rgba(15, 23, 42, 0.85)");
+        ctx.fillStyle = winGrad;
+        ctx.fillRect(-hw, -hh, hw * 2, hh);
+
+        // Deployed Airbag (if triggered by impact)
+        if (car.airbagDeployed) {
+          ctx.fillStyle = "rgba(248, 250, 252, 0.92)";
+          ctx.strokeStyle = "#94a3b8";
+          ctx.lineWidth = 1;
+          ctx.beginPath();
+          ctx.arc(hw * 0.23, hh - 80, 14, 0, Math.PI * 2);
+          ctx.fill();
+          ctx.stroke();
+        }
+
+        // Crash-Test Dummy Silhouette (tilts forward on deceleration)
+        ctx.save();
+        ctx.translate(hw * 0.04, hh - 62);
+        ctx.rotate(car.dummyPitch);
+        // Torso
+        ctx.fillStyle = "#facc15";
+        ctx.fillRect(-6, -22, 12, 22);
+        // Seatbelt strap
+        ctx.strokeStyle = "#111827";
+        ctx.lineWidth = 2.5;
+        ctx.beginPath();
+        ctx.moveTo(-6, -20);
+        ctx.lineTo(6, -2);
+        ctx.stroke();
+        // Dummy Head with fiducial cross
+        ctx.fillStyle = "#facc15";
+        ctx.beginPath();
+        ctx.arc(1, -30, 7.5, 0, Math.PI * 2);
+        ctx.fill();
+        ctx.fillStyle = "#111827";
+        ctx.beginPath();
+        ctx.arc(1, -30, 3, 0, Math.PI, true);
+        ctx.fill();
+        ctx.restore();
+
+        // B-Pillar
+        ctx.fillStyle = "#1e293b";
+        ctx.fillRect(-10, -hh + 8, 8, hh);
+        ctx.restore();
+
+        // 3. Crash-Test Livery Stripes & Photogrammetry Fiducial Targets
+        ctx.fillStyle = "#111827";
+        ctx.fillRect(-hw * 0.55, hh - 46, hw * 1.1, 8);
+
+        drawFiducialMarker(-hw * 0.45, hh - 42, 7.5);
+        drawFiducialMarker(hw * 0.12, hh - 42, 7.5);
+        drawFiducialMarker(frontX - 36, hh - 42, 6.5);
+
+        // Headlight & Taillight
+        ctx.fillStyle = car.crumple > 0.08 ? "#94a3b8" : "#fef08a";
+        ctx.fillRect(frontX - 9, hh - 55, 8, 12);
+        ctx.fillStyle = "#ef4444";
+        ctx.fillRect(-hw + 1, hh - 54, 7, 13);
+
+        // 4. Front & Rear Wheels with Rotating Fiducial Quadrants
+        const wheelR = 0.34 * scale;
+        const rearWheelX = -hw * 0.60;
+        const frontWheelX = Math.min(hw * 0.60, frontX - wheelR - 6);
+        const wheelY = hh - wheelR;
+
+        drawWheel(rearWheelX, wheelY, wheelR, car.wheelAngle);
+        drawWheel(frontWheelX, wheelY, wheelR, car.wheelAngle);
+
+        ctx.restore();
+      }
+
+      function drawFiducialMarker(x, y, r) {
+        ctx.save();
+        ctx.translate(x, y);
+        ctx.fillStyle = "#facc15";
+        ctx.beginPath();
+        ctx.arc(0, 0, r, 0, Math.PI * 2);
+        ctx.fill();
+
+        ctx.fillStyle = "#111827";
+        ctx.beginPath();
+        ctx.moveTo(0, 0);
+        ctx.arc(0, 0, r, 0, Math.PI * 0.5);
+        ctx.closePath();
+        ctx.fill();
+
+        ctx.beginPath();
+        ctx.moveTo(0, 0);
+        ctx.arc(0, 0, r, Math.PI, Math.PI * 1.5);
+        ctx.closePath();
+        ctx.fill();
+
+        ctx.strokeStyle = "#111827";
+        ctx.lineWidth = 1;
+        ctx.beginPath();
+        ctx.arc(0, 0, r, 0, Math.PI * 2);
+        ctx.stroke();
+        ctx.restore();
+      }
+
+      function drawWheel(wx, wy, r, angle) {
+        ctx.save();
+        ctx.translate(wx, wy);
+
+        // Wheel arch cutout shadow
+        ctx.fillStyle = "#090d16";
+        ctx.beginPath();
+        ctx.arc(0, 0, r + 4, 0, Math.PI * 2);
+        ctx.fill();
+
+        ctx.rotate(angle);
+
+        // Rubber tire
+        ctx.fillStyle = "#1e293b";
+        ctx.strokeStyle = "#0f172a";
+        ctx.lineWidth = 2;
+        ctx.beginPath();
+        ctx.arc(0, 0, r, 0, Math.PI * 2);
+        ctx.fill();
+        ctx.stroke();
+
+        // Alloy rim
+        const rimR = r * 0.64;
+        ctx.fillStyle = "#cbd5e1";
+        ctx.beginPath();
+        ctx.arc(0, 0, rimR, 0, Math.PI * 2);
+        ctx.fill();
+
+        // Crash test wheel rotation fiducial quadrants
+        drawFiducialMarker(0, 0, rimR * 0.78);
+
+        ctx.restore();
+      }
+
+      function drawDustParticles(scale, groundY) {
+        for (let i = 0; i < dustParticles.length; i++) {
+          const p = dustParticles[i];
+          const px = p.x * scale;
+          const py = groundY - p.y * scale;
+          const fade = Math.max(0, 1 - p.life / p.maxLife);
+          const alpha = p.alpha * fade;
+
+          if (p.isChip) {
+            ctx.fillStyle = "rgba(180, 83, 58, " + alpha.toFixed(2) + ")";
+            ctx.fillRect(px - p.size * 0.5, py - p.size * 0.5, p.size, p.size);
+          } else {
+            ctx.fillStyle = "rgba(203, 213, 225, " + alpha.toFixed(2) + ")";
+            ctx.beginPath();
+            ctx.arc(px, py, p.size, 0, Math.PI * 2);
+            ctx.fill();
+          }
+        }
+      }
+
+      // =========================================================================
+      // EVENT LISTENERS & CONTROLS
+      // =========================================================================
+      function onSettingInput() {
+        settings.carSpeed = parseFloat(inpCarSpeed.value);
+        settings.wallColumns = parseInt(inpWallCols.value, 10);
+        settings.wallRows = parseInt(inpWallRows.value, 10);
+        settings.wallDepthLayers = parseInt(inpWallLayers.value, 10);
+        settings.brickMass = parseFloat(inpBrickMass.value);
+
+        syncSettingsLabels();
+        resetExperiment();
+      }
+
+      inpCarSpeed.addEventListener("input", onSettingInput);
+      inpWallCols.addEventListener("input", onSettingInput);
+      inpWallRows.addEventListener("input", onSettingInput);
+      inpWallLayers.addEventListener("input", onSettingInput);
+      inpBrickMass.addEventListener("input", onSettingInput);
+
+      btnTest.addEventListener("click", function () {
+        startExperiment();
+      });
+
+      btnReset.addEventListener("click", function () {
+        resetExperiment();
+      });
+
+      btnDefaults.addEventListener("click", function () {
+        settings.carSpeed = DEFAULTS.carSpeed;
+        settings.wallColumns = DEFAULTS.wallColumns;
+        settings.wallRows = DEFAULTS.wallRows;
+        settings.wallDepthLayers = DEFAULTS.wallDepthLayers;
+        settings.brickMass = DEFAULTS.brickMass;
+
+        inpCarSpeed.value = String(DEFAULTS.carSpeed);
+        inpWallCols.value = String(DEFAULTS.wallColumns);
+        inpWallRows.value = String(DEFAULTS.wallRows);
+        inpWallLayers.value = String(DEFAULTS.wallDepthLayers);
+        inpBrickMass.value = String(DEFAULTS.brickMass);
+
+        syncSettingsLabels();
+        resetExperiment();
+      });
+
+      window.addEventListener("keydown", function (e) {
+        if (e.target && e.target.tagName === "INPUT") return;
+        if (e.code === "Space" || e.code === "Enter") {
+          e.preventDefault();
+          startExperiment();
+        } else if (e.code === "KeyR") {
+          e.preventDefault();
+          resetExperiment();
+        }
+      });
+
+      window.addEventListener("resize", function () {
+        resizeCanvas();
+        renderScene();
+      });
+
+      // =========================================================================
+      // MAIN ANIMATION LOOP
+      // =========================================================================
+      function tick() {
+        stepPhysics();
+        renderScene();
+        requestAnimationFrame(tick);
+      }
+
+      // Initialize default state on first load
+      resizeCanvas();
+      syncSettingsLabels();
+      resetExperiment();
+      requestAnimationFrame(tick);
+    })();
+  </script>
+</body>
+</html>

