// =========================================================================
// MORTAR FRACTURE & STRUCTURAL SUPPORT SOLVER
// =========================================================================
function getBrickFractureThreshold(b) {
  const overburden = settings.wallRows - b.row;
  const depthFactor = 0.80 + 0.22 * settings.wallDepthLayers;
  return b.mass * (1.20 + 0.20 * overburden * DEFAULTS.brickFriction) * depthFactor;
}

function unbondBrick(b, impulseX, impulseY, omegaKick) {
  if (!b.bonded) return;
  b.bonded = false;
  b.sleeping = false;
  b.sleepTimer = 0;
  b.vx += impulseX * b.invMass;
  b.vy += impulseY * b.invMass;
  b.omega += omegaKick || 0;

  if (dustParticles.length < 280 && nextVisualRand() < 0.55) {
    spawnDust(b.x, b.y, 2);
  }
}

function applyStressToBondedBrick(b, jx, jy, cx, cy) {
  const jMag = Math.hypot(jx, jy);
  if (jMag <= 0) return;

  b.stressAccum += jMag;

  // Propagate compressive/shear stress wave into adjacent bonded bricks
  const nbrs = b.neighbors;
  const waveShare = 0.44 / Math.max(1, nbrs.length * 0.5);
  for (let i = 0; i < nbrs.length; i++) {
    const nb = nbrs[i];
    if (nb.bonded) {
      nb.stressAccum += jMag * waveShare;
    }
  }

  const crit = getBrickFractureThreshold(b);
  if (b.stressAccum >= crit) {
    const rx = cx - b.x;
    const ry = cy - b.y;
    const torqueImpulse = (rx * jy - ry * jx) * b.invInertia;
    unbondBrick(b, jx * 0.85, jy * 0.85, torqueImpulse);

    // Check if neighbors also exceeded their fracture limit from the propagated shockwave
    for (let i = 0; i < nbrs.length; i++) {
      const nb = nbrs[i];
      if (nb.bonded && nb.stressAccum >= getBrickFractureThreshold(nb)) {
        const dirY = (nb.y - b.y) * 0.35;
        const rotKick = (nb.row > b.row) ? 1.8 : -0.8;
        unbondBrick(nb, jx * 0.32, jy * 0.32 + dirY, rotKick);
      }
    }
  }
}

function updateWallStructuralSupport() {
  // Sweep from bottom row up: if supporting bricks below a bonded brick are gone, it loses support and falls
  for (let l = 0; l < bricksByLayer.length; l++) {
    const layerBricks = bricksByLayer[l];
    for (let i = 0; i < layerBricks.length; i++) {
      const b = layerBricks[i];
      if (!b.bonded) continue;

      // Decay transient sub-critical elastic stress slightly
      b.stressAccum *= 0.96;

      if (b.row > 0) {
        const supports = b.supportsBelow;
        let intactSupports = 0;
        let leftSupportGone = false;
        let rightSupportGone = false;

        for (let s = 0; s < supports.length; s++) {
          const sup = supports[s];
          if (sup.bonded) {
            intactSupports++;
          } else {
            if (sup.x <= b.x) leftSupportGone = true;
            if (sup.x >= b.x) rightSupportGone = true;
          }
        }

        // If all supports below are gone, or overhanging without support below
        if (intactSupports === 0 || (supports.length >= 2 && intactSupports === 1 && b.stressAccum > getBrickFractureThreshold(b) * 0.35)) {
          const toppleOmega = leftSupportGone && !rightSupportGone ? 1.6 : (rightSupportGone && !leftSupportGone ? -1.6 : 0.4);
          unbondBrick(b, 0, -0.05 * b.mass, toppleOmega);
        }
      }
    }
  }

  // Also enforce soft cohesive coupling between recently unbonded bricks that still share unbroken mortar
  const massScale = Math.pow(settings.brickMass / 2.5, 0.85);
  const maxStretch = 0.014;
  const maxImpulse = 3.2 * massScale;

  for (let i = 0; i < mortarJoints.length; i++) {
    const j = mortarJoints[i];
    if (j.broken) continue;

    const a = j.a;
    const b = j.b;
    if (a.bonded && b.bonded) continue;
    if (a.bonded !== b.bonded) {
      j.broken = true;
      continue;
    }

    const avgAngle = (a.angle + b.angle) * 0.5;
    const cos = Math.cos(avgAngle);
    const sin = Math.sin(avgAngle);
    const targetDx = j.dx0 * cos - j.dy0 * sin;
    const targetDy = j.dx0 * sin + j.dy0 * cos;

    const errX = (b.x - a.x) - targetDx;
    const errY = (b.y - a.y) - targetDy;
    if (Math.hypot(errX, errY) > maxStretch || Math.abs(b.angle - a.angle) > 0.08) {
      j.broken = true;
      continue;
    }

    const jx = (errX * 12.0 + (b.vx - a.vx) * 0.3) * a.mass;
    const jy = (errY * 12.0 + (b.vy - a.vy) * 0.3) * a.mass;
    if (Math.hypot(jx, jy) > maxImpulse) {
      j.broken = true;
      continue;
    }

    a.vx += jx * a.invMass;
    a.vy += jy * a.invMass;
    b.vx -= jx * b.invMass;
    b.vy -= jy * b.invMass;
  }
}

