function resolveTwoBodyContact(a, b, cx, cy, nx, ny, depth, restitution, friction, isCarImpact) {
  const aBonded = Boolean(a.bonded);
  const bBonded = Boolean(b.bonded);
  if (aBonded && bBonded) return 0;

  // If a brick is still bonded to the coherent masonry wall, its effective structural resistance
  // includes the intact courses backing it in its row
  const behindCols = bBonded ? Math.max(1, settings.wallColumns - b.col) : 1;
  const structuralMult = bBonded ? (1 + 0.45 * behindCols * Math.sqrt(settings.wallDepthLayers)) : 1;

  const invMassA = aBonded ? 0 : a.invMass;
  const invInertiaA = aBonded ? 0 : a.invInertia;
  const invMassB = bBonded ? (b.invMass / structuralMult) : b.invMass;
  const invInertiaB = bBonded ? 0 : b.invInertia;

  const rAx = cx - a.x;
  const rAy = cy - a.y;
  const rBx = cx - b.x;
  const rBy = cy - b.y;

  const vAx = a.vx - a.omega * rAy;
  const vAy = a.vy + a.omega * rAx;
  const vBx = b.vx - b.omega * rBy;
  const vBy = b.vy + b.omega * rBx;

  const rvx = vBx - vAx;
  const rvy = vBy - vAy;

  const velAlongNormal = rvx * nx + rvy * ny;

  // Wake sleeping brick only if real impact velocity exceeds threshold
  if (a.sleeping && -velAlongNormal > 0.38) { a.sleeping = false; a.sleepTimer = 0; }
  if (b.sleeping && -velAlongNormal > 0.38) { b.sleeping = false; b.sleepTimer = 0; }

  const rACrossN = rAx * ny - rAy * nx;
  const rBCrossN = rBx * ny - rBy * nx;
  const invMassSum = invMassA + invMassB +
                     rACrossN * rACrossN * invInertiaA +
                     rBCrossN * rBCrossN * invInertiaB;
  if (invMassSum <= 0) return 0;

  // Baumgarte stabilization bias
  const slop = 0.0015;
  const beta = isCarImpact ? 0.25 : 0.16;
  const bias = (velAlongNormal < 0.08) ? Math.max(0, depth - slop) * (beta / SUB_DT) : 0;

  let e = (-velAlongNormal > 0.75) ? restitution : 0;
  let jn = (-(1 + e) * velAlongNormal + bias) / invMassSum;
  if (jn < 0) jn = 0;

  const impulseX = jn * nx;
  const impulseY = jn * ny;

  if (!aBonded) {
    a.vx -= impulseX * invMassA;
    a.vy -= impulseY * invMassA;
    a.omega -= (rAx * impulseY - rAy * impulseX) * invInertiaA;
  } else {
    applyStressToBondedBrick(a, -impulseX, -impulseY, cx, cy);
  }

  if (!bBonded) {
    b.vx += impulseX * invMassB;
    b.vy += impulseY * invMassB;
    b.omega += (rBx * impulseY - rBy * impulseX) * invInertiaB;
  } else {
    applyStressToBondedBrick(b, impulseX, impulseY, cx, cy);
  }

  // Recompute relative velocity for friction impulse
  const vAx2 = a.vx - a.omega * rAy;
  const vAy2 = a.vy + a.omega * rAx;
  const vBx2 = b.vx - b.omega * rBy;
  const vBy2 = b.vy + b.omega * rBx;
  const rvx2 = vBx2 - vAx2;
  const rvy2 = vBy2 - vAy2;

  const tx = -ny;
  const ty = nx;
  const vt = rvx2 * tx + rvy2 * ty;

  const rACrossT = rAx * ty - rAy * tx;
  const rBCrossT = rBx * ty - rBy * tx;
  const invMassTangent = invMassA + invMassB +
                         rACrossT * rACrossT * invInertiaA +
                         rBCrossT * rBCrossT * invInertiaB;

  if (invMassTangent > 0) {
    let jt = -vt / invMassTangent;
    const maxFriction = jn * friction;
    if (jt > maxFriction) jt = maxFriction;
    if (jt < -maxFriction) jt = -maxFriction;

    const fImpulseX = jt * tx;
    const fImpulseY = jt * ty;

    if (!aBonded) {
      a.vx -= fImpulseX * invMassA;
      a.vy -= fImpulseY * invMassA;
      a.omega -= (rAx * fImpulseY - rAy * fImpulseX) * invInertiaA;
    }
    if (!bBonded) {
      b.vx += fImpulseX * invMassB;
      b.vy += fImpulseY * invMassB;
      b.omega += (rBx * fImpulseY - rBy * fImpulseX) * invInertiaB;
    }
  }

  return jn;
}

function resolveTwoBodyContact(a, b, cx, cy, nx, ny, depth, restitution, friction, isCarImpact) {
  const aBonded = Boolean(a.bonded);
  const bBonded = Boolean(b.bonded);
  if (aBonded && bBonded) return 0;

  // If a brick is still bonded to the coherent masonry wall, its effective structural resistance
  // includes the intact courses backing it in its row
  const behindCols = bBonded ? Math.max(1, settings.wallColumns - b.col) : 1;
  const structuralMult = bBonded ? (1 + 0.45 * behindCols * Math.sqrt(settings.wallDepthLayers)) : 1;

  const invMassA = aBonded ? 0 : a.invMass;
  const invInertiaA = aBonded ? 0 : a.invInertia;
  const invMassB = bBonded ? (b.invMass / structuralMult) : b.invMass;
  const invInertiaB = bBonded ? 0 : b.invInertia;

  const rAx = cx - a.x;
  const rAy = cy - a.y;
  const rBx = cx - b.x;
  const rBy = cy - b.y;

  const vAx = a.vx - a.omega * rAy;
  const vAy = a.vy + a.omega * rAx;
  const vBx = b.vx - b.omega * rBy;
  const vBy = b.vy + b.omega * rBx;

  const rvx = vBx - vAx;
  const rvy = vBy - vAy;

  const velAlongNormal = rvx * nx + rvy * ny;

  // Wake sleeping brick only if real impact velocity exceeds threshold
  if (a.sleeping && -velAlongNormal > 0.38) { a.sleeping = false; a.sleepTimer = 0; }
  if (b.sleeping && -velAlongNormal > 0.38) { b.sleeping = false; b.sleepTimer = 0; }

  const rACrossN = rAx * ny - rAy * nx;
  const rBCrossN = rBx * ny - rBy * nx;
  const invMassSum = invMassA + invMassB +
                     rACrossN * rACrossN * invInertiaA +
                     rBCrossN * rBCrossN * invInertiaB;
  if (invMassSum <= 0) return 0;

  // Baumgarte stabilization bias
  const slop = 0.0015;
  const beta = isCarImpact ? 0.25 : 0.16;
  const bias = (velAlongNormal < 0.08) ? Math.max(0, depth - slop) * (beta / SUB_DT) : 0;

  let e = (-velAlongNormal > 0.75) ? restitution : 0;
  let jn = (-(1 + e) * velAlongNormal + bias) / invMassSum;
  if (jn < 0) jn = 0;

  const impulseX = jn * nx;
  const impulseY = jn * ny;

  if (!aBonded) {
    a.vx -= impulseX * invMassA;
    a.vy -= impulseY * invMassA;
    a.omega -= (rAx * impulseY - rAy * impulseX) * invInertiaA;
  } else {
    applyStressToBondedBrick(a, -impulseX, -impulseY, cx, cy);
  }

  if (!bBonded) {
    b.vx += impulseX * invMassB;
    b.vy += impulseY * invMassB;
    b.omega += (rBx * impulseY - rBy * impulseX) * invInertiaB;
  } else {
    applyStressToBondedBrick(b, impulseX, impulseY, cx, cy);
  }

  // Recompute relative velocity for friction impulse
  const vAx2 = a.vx - a.omega * rAy;
  const vAy2 = a.vy + a.omega * rAx;
  const vBx2 = b.vx - b.omega * rBy;
  const vBy2 = b.vy + b.omega * rBx;
  const rvx2 = vBx2 - vAx2;
  const rvy2 = vBy2 - vAy2;

  const tx = -ny;
  const ty = nx;
  const vt = rvx2 * tx + rvy2 * ty;

  const rACrossT = rAx * ty - rAy * tx;
  const rBCrossT = rBx * ty - rBy * tx;
  const invMassTangent = invMassA + invMassB +
                         rACrossT * rACrossT * invInertiaA +
                         rBCrossT * rBCrossT * invInertiaB;

  if (invMassTangent > 0) {
    let jt = -vt / invMassTangent;
    const maxFriction = jn * friction;
    if (jt > maxFriction) jt = maxFriction;
    if (jt < -maxFriction) jt = -maxFriction;

    const fImpulseX = jt * tx;
    const fImpulseY = jt * ty;

    if (!aBonded) {
      a.vx -= fImpulseX * invMassA;
      a.vy -= fImpulseY * invMassA;
      a.omega -= (rAx * fImpulseY - rAy * fImpulseX) * invInertiaA;
    }
    if (!bBonded) {
      b.vx += fImpulseX * invMassB;
      b.vy += fImpulseY * invMassB;
      b.omega += (rBx * fImpulseY - rBy * fImpulseX) * invInertiaB;
    }
  }

  return jn;
}

