  // 2. Integrate Unbonded Bricks (bonded bricks remain in static equilibrium until fractured)
  if (impactOccurred) {
    for (let i = 0; i < bricks.length; i++) {
      const b = bricks[i];
      if (b.bonded || b.sleeping) continue;

      b.vy -= g * SUB_DT;

      // Mild aerodynamic drag & angular damping for physical stability
      b.vx *= 0.9992;
      b.vy *= 0.9992;
      b.omega *= 0.994;

      b.x += b.vx * SUB_DT;
      b.y += b.vy * SUB_DT;
      b.angle += b.omega * SUB_DT;
      updateBrickTransform(b);
    }

    // 3. Update Wall Structural Support & Mortar Cohesion
    updateWallStructuralSupport();

    // 4. Collect Contact Manifolds for Current Substep
    const carVerts = getCarHullVertices(car);
    const carContacts = [];
    for (let i = 0; i < bricks.length; i++) {
      const b = bricks[i];
      const m = collideCarBrick(car, carVerts, b);
      if (m) {
        b.sleeping = false;
        b.sleepTimer = 0;
        carContacts.push({ brick: b, m: m });
      }
    }

    const brickContacts = [];
    for (let l = 0; l < bricksByLayer.length; l++) {
      const layerBricks = bricksByLayer[l];
      const n = layerBricks.length;
      for (let i = 0; i < n; i++) {
        const bA = layerBricks[i];
        for (let j = i + 1; j < n; j++) {
          const bB = layerBricks[j];
          if ((bA.bonded || bA.sleeping) && (bB.bonded || bB.sleeping)) continue;
          if (Math.abs(bB.x - bA.x) > 0.56 || Math.abs(bB.y - bA.y) > 0.56) continue;
