args.streamContent:
// =========================================================================
// MORTAR FRACTURE & STRUCTURAL SUPPORT SOLVER
// =========================================================================
function getBrickFractureThreshold(b) {
  const overburden = settings.wallRows - b.row;
  const depthFactor = 0.85 + 0.30 * settings.wallDepthLayers;
  return b.mass * (1.85 + 0.38 * overburden * DEFAULTS.brickFriction) * depthFactor;
}

function unbondBrick(b, impulseX, impulseY, omegaKick) {
  if (!b.bonded) return;
  b.bonded = false;
  b.sleeping = false;
  b.sleepTimer = 0;
  b.vx += impulseX * b.invMass;
  b.vy += impulseY * b.invMass;
  b.omega += omegaKick || 0;

  if (dustParticles.length < 280 && nextVisualRand() < 0.55) {
    spawnDust(b.x, b.y, 2);
  }
}

function applyStressToBondedBrick(b, jx, jy, cx, cy) {
  const jMag = Math.hypot(jx, jy);
  if (jMag <= 0) return;

  // Accumulate physical impulse stress (scaled by solver iterations)
  const stressDelta = jMag / SOLVER_ITERATIONS;
  b.stressAccum += stressDelta;

  const crit = getBrickFractureThreshold(b);
  if (b.stressAccum >= crit) {
    const rx = cx - b.x;
    const ry = cy - b.y;
    const torqueImpulse = (rx * jy - ry * jx) * b.invInertia * 0.35;
    unbondBrick(b, jx * 0.45, jy * 0.45, torqueImpulse);
  }
}

function updateWallStructuralSupport() {
  // Sweep from bottom row up: if supporting bricks below a bonded brick have displaced, it loses support and falls
  for (let l = 0; l < bricksByLayer.length; l++) {
    const layerBricks = bricksByLayer[l];
    for (let i = 0; i < layerBricks.length; i++) {
      const b = layerBricks[i];
      if (!b.bonded) continue;

      // Decay sub-critical elastic stress
      b.stressAccum *= 0.92;

      if (b.row > 0) {
        const supports = b.supportsBelow;
        let validSupports = 0;
        let leftSupportGone = false;
        let rightSupportGone = false;

        for (let s = 0; s < supports.length; s++) {
          const sup = supports[s];
          const supDisplaced = !sup.bonded &&
            (Math.abs(sup.x - sup.initialX) > 0.055 || Math.abs(sup.y - sup.initialY) > 0.035);
          if (!supDisplaced) {
            validSupports++;
          } else {
            if (sup.initialX <= b.initialX) leftSupportGone = true;
            if (sup.initialX >= b.initialX) rightSupportGone = true;
          }
        }

        // If supports underneath have been knocked away, brick unbonds and falls under gravity
        if (validSupports === 0 || (supports.length >= 2 && validSupports === 1 && b.stressAccum > getBrickFractureThreshold(b) * 0.45)) {
          const toppleOmega = leftSupportGone && !rightSupportGone ? 1.35 : (rightSupportGone && !leftSupportGone ? -1.35 : 0.25);
          unbondBrick(b, 0, 0, toppleOmega);
        }
      }
    }
  }

  // Inter-layer shear transfer between overlapping wythes (depth layers)
  for (let i = 0; i < depthCouplings.length; i++) {
    const d = depthCouplings[i];
    if (d.broken) continue;
    const a = d.a;
    const b = d.b;
    if (a.bonded && b.bonded) continue;

    const errX = (b.x - a.x) - d.dx0;
    const errY = (b.y - a.y) - d.dy0;
    if (Math.hypot(errX, errY) > 0.14) {
      d.broken = true;
      continue;
    }

    // Transfer shear force between front wythe and back wythe before collar joint shears
    const shearX = (b.vx - a.vx) * 0.12 * a.mass;
    const shearY = (b.vy - a.vy) * 0.12 * a.mass;
    if (!a.bonded && !b.bonded) {
      a.vx += shearX * a.invMass;
      a.vy += shearY * a.invMass;
      b.vx -= shearX * b.invMass;
      b.vy -= shearY * b.invMass;
    } else if (!a.bonded && b.bonded) {
      applyStressToBondedBrick(b, -shearX * 3.5, -shearY * 3.5, b.x, b.y);
    } else if (a.bonded && !b.bonded) {
      applyStressToBondedBrick(a, shearX * 3.5, shearY * 3.5, a.x, a.y);
    }
  }
}

// =========================================================================
// MORTAR FRACTURE & STRUCTURAL SUPPORT SOLVER
// =========================================================================
function getBrickFractureThreshold(b) {
  const overburden = settings.wallRows - b.row;
  const depthFactor = 0.85 + 0.30 * settings.wallDepthLayers;
  return b.mass * (1.85 + 0.38 * overburden * DEFAULTS.brickFriction) * depthFactor;
}

function unbondBrick(b, impulseX, impulseY, omegaKick) {
  if (!b.bonded) return;
  b.bonded = false;
  b.sleeping = false;
  b.sleepTimer = 0;
  b.vx += impulseX * b.invMass;
  b.vy += impulseY * b.invMass;
  b.omega += omegaKick || 0;

  if (dustParticles.length < 280 && nextVisualRand() < 0.55) {
    spawnDust(b.x, b.y, 2);
