function resolveBrickGround(b) {
  const verts = getBrickVertices(b);
  const e = DEFAULTS.brickRestitution * 0.5;
  const mu = DEFAULTS.groundFriction;

  for (let i = 0; i < 4; i++) {
    const v = verts[i];
    if (v.y <= 0.002) {
      const rx = v.x - b.x;
      const ry = v.y - b.y;

      const vx = b.vx - b.omega * ry;
      const vy = b.vy + b.omega * rx;

      const rCrossN = rx; // normal is (0, 1)
      const kN = b.invMass + rCrossN * rCrossN * b.invInertia;

      const effE = (-vy > 0.9) ? e : 0;
      let jn = (vy < 0) ? (-(1 + effE) * vy) / kN : (b.mass * DEFAULTS.gravity * SUB_DT * 0.5);
      if (jn > 0) {
        if (vy < 0) {
          b.vy += jn * b.invMass;
          b.omega += rx * jn * b.invInertia;
        }

        // Ground friction along tangent (1, 0)
        const vx2 = b.vx - b.omega * ry;
        const rCrossT = -ry;
        const kT = b.invMass + rCrossT * rCrossT * b.invInertia;
        let jt = -vx2 / kT;
        const maxF = jn * mu;
        if (jt > maxF) jt = maxF;
        if (jt < -maxF) jt = -maxF;

        b.vx += jt * b.invMass;
        b.omega += (-ry * jt) * b.invInertia;
      }
    }
  }
}

