  // Find the support edge on A (along +normal) and on B (along -normal) and clip along tangent
  const vertsA = getBrickVertices(a);
  const vertsB = getBrickVertices(b);

  const edgeA = getSupportEdge(vertsA, bestAxisX, bestAxisY);
  const edgeB = getSupportEdge(vertsB, -bestAxisX, -bestAxisY);

  const tx = -bestAxisY;
  const ty = bestAxisX;

  const tA0 = edgeA[0].x * tx + edgeA[0].y * ty;
  const tA1 = edgeA[1].x * tx + edgeA[1].y * ty;
  const tB0 = edgeB[0].x * tx + edgeB[0].y * ty;
  const tB1 = edgeB[1].x * tx + edgeB[1].y * ty;

  const minTA = Math.min(tA0, tA1), maxTA = Math.max(tA0, tA1);
  const minTB = Math.min(tB0, tB1), maxTB = Math.max(tB0, tB1);

  const clipT0 = Math.max(minTA, minTB);
  const clipT1 = Math.min(maxTA, maxTB);

  const contacts = [];
  if (clipT1 >= clipT0 - 0.005) {
    const p0 = sampleEdgeAtTangent(edgeB, tB0, tB1, clipT0);
    contacts.push(p0);
    if (clipT1 - clipT0 > 0.008) {
      const p1 = sampleEdgeAtTangent(edgeB, tB0, tB1, clipT1);
      contacts.push(p1);
    }
  } else {
    contacts.push({
      x: (edgeA[0].x + edgeB[0].x) * 0.5,
      y: (edgeA[0].y + edgeB[0].y) * 0.5
    });
  }

  return {
    nx: bestAxisX,
    ny: bestAxisY,
    depth: minOverlap,
    contacts: contacts
  };
}

function getSupportEdge(verts, nx, ny) {
  let bestIdx = 0;
  let bestDot = -Infinity;
  for (let i = 0; i < 4; i++) {
    const d = verts[i].x * nx + verts[i].y * ny;
    if (d > bestDot) {
      bestDot = d;
      bestIdx = i;
    }
  }
  const prevIdx = (bestIdx + 3) % 4;
  const nextIdx = (bestIdx + 1) % 4;
  const dPrev = verts[prevIdx].x * nx + verts[prevIdx].y * ny;
  const dNext = verts[nextIdx].x * nx + verts[nextIdx].y * ny;
  if (dPrev > dNext) {
    return [verts[prevIdx], verts[bestIdx]];
  }
  return [verts[bestIdx], verts[nextIdx]];
}

function sampleEdgeAtTangent(edge, t0, t1, t) {
  const span = t1 - t0;
  if (Math.abs(span) < 1e-6) {
    return { x: edge[0].x, y: edge[0].y };
  }
  const u = Math.max(0, Math.min(1, (t - t0) / span));
  return {
    x: edge[0].x + (edge[1].x - edge[0].x) * u,
    y: edge[0].y + (edge[1].y - edge[0].y) * u
  };
}

