// Pure velocity constraint in velocity solver (positional overlap is resolved in NGS position pass without polluting velocity)
let e = (-velAlongNormal > 0.85) ? restitution : 0;
let jn = (-(1 + e) * velAlongNormal) / invMassSum;
if (jn < 0) jn = 0;

if (jn > 0) {
  const impulseX = jn * nx;
  const impulseY = jn * ny;

  if (!aBonded) {
    a.vx -= impulseX * invMassA;
    a.vy -= impulseY * invMassA;
    a.omega -= (rAx * impulseY - rAy * impulseX) * invInertiaA;
  } else {
    applyStressToBondedBrick(a, -impulseX, -impulseY, cx, cy);
  }

  if (!bBonded) {
    b.vx += impulseX * invMassB;
    b.vy += impulseY * invMassB;
    b.omega += (rBx * impulseY - rBy * impulseX) * invInertiaB;
  } else {
    applyStressToBondedBrick(b, impulseX, impulseY, cx, cy);
  }
}

// Recompute relative velocity for friction impulse
const vAx2 = a.vx - a.omega * rAy;
const vAy2 = a.vy + a.omega * rAx;
const vBx2 = b.vx - b.omega * rBy;
const vBy2 = b.vy + b.omega * rBx;
const rvx2 = vBx2 - vAx2;
const rvy2 = vBy2 - vAy2;

const tx = -ny;
const ty = nx;
const vt = rvx2 * tx + rvy2 * ty;

const rACrossT = rAx * ty - rAy * tx;
const rBCrossT = rBx * ty - rBy * tx;
const invMassTangent = invMassA + invMassB +
                       rACrossT * rACrossT * invInertiaA +
                       rBCrossT * rBCrossT * invInertiaB;

if (invMassTangent > 0) {
  let jt = -vt / invMassTangent;
  const restingLoad = (depth > 0.001) ? (Math.min(a.mass, b.mass) * DEFAULTS.gravity * SUB_DT / SOLVER_ITERATIONS) : 0;
  const maxFriction = (jn + restingLoad) * friction;
  if (jt > maxFriction) jt = maxFriction;
  if (jt < -maxFriction) jt = -maxFriction;

