node -e '
const fs = require("fs");
const html = fs.readFileSync("index.html", "utf8");
const scriptMatch = html.match(/<script>([\s\S]*?)<\/script>/);
const elements = {};
const makeEl = (id) => ({
  id, value: "", textContent: "", className: "",
  classList: { add(){}, remove(){} },
  addEventListener(ev, fn) { this["on_" + ev] = fn; },
  getBoundingClientRect() { return { width: 1440, height: 760 }; },
  getContext() { return new Proxy({}, { get: (t, prop) => prop === "createLinearGradient" ? () => ({ addColorStop(){} }) : () => {} }); }
});
["simCanvas","canvasStage","btnTest","btnReset","btnDefaults","inpCarSpeed","inpWallCols","inpWallRows","inpWallLayers","inpBrickMass","valCarSpeed","valWallCols","valWallRows","valWallLayers","valBrickMass","statusPill","statusText","telSpeed","telSpeedKmh","telTime","telMoving","telTotalBricks","telDisplaced","telDisplacedPct","telWallMass","telPeakG","telImpulse"].forEach(id => elements[id] = makeEl(id));
elements.inpCarSpeed.value = "22"; elements.inpWallCols.value = "12"; elements.inpWallRows.value = "8"; elements.inpWallLayers.value = "2"; elements.inpBrickMass.value = "2.5";
let rafCb = null;
global.window = { devicePixelRatio: 1, addEventListener(){}, requestAnimationFrame(cb) { rafCb = cb; } };
global.requestAnimationFrame = (cb) => { rafCb = cb; };
global.document = { body: {}, getElementById(id) { return elements[id] || makeEl(id); } };
global.getComputedStyle = () => ({ getPropertyValue: () => "monospace" });

eval(scriptMatch[1]);
function runFrames(n) { for (let i = 0; i < n; i++) rafCb(); }

elements.btnTest.on_click();
for (let f = 1; f <= 270; f++) {
  rafCb();
  if (f % 30 === 0 || f === 10) {
    console.log(`Default f=${f} (t=${elements.telTime.textContent}s): status=${elements.statusText.textContent}, carSpeed=${elements.telSpeed.textContent}, moving=${elements.telMoving.textContent}, displaced=${elements.telDisplaced.textContent} ${elements.telDisplacedPct.textContent}`);
  }
}
'

