// Post-frame support graph & sleep stabilization
let movingCount = 0;
if (impactOccurred) {
  for (let i = 0; i < bricks.length; i++) {
    const b = bricks[i];
    if (b.bonded) {
      b.supported = true;
      continue;
    }
    const minY = b.y - (Math.abs(b.sin) * b.hw + Math.abs(b.cos) * b.hh);
    b.supported = (minY <= 0.015);
  }

  // Propagate vertical support upward through resting brick piles and car hood/roof
  for (let pass = 0; pass < 6; pass++) {
    for (let l = 0; l < bricksByLayer.length; l++) {
      const layerBricks = bricksByLayer[l];
      const n = layerBricks.length;
      for (let i = 0; i < n; i++) {
        const a = layerBricks[i];
        for (let j = i + 1; j < n; j++) {
          const b = layerBricks[j];
          if (a.supported === b.supported) continue;
          if (Math.abs(b.x - a.x) > 0.52 || Math.abs(b.y - a.y) > 0.52) continue;
          const m = collideBrickBrick(a, b);
          if (m && m.depth > 0.0002) {
            if (a.supported && m.ny > 0.35) b.supported = true;
            else if (b.supported && m.ny < -0.35) a.supported = true;
          }
        }
      }
    }
  }

  // Also mark bricks resting on the stopped car as supported
  if (Math.abs(car.vx) < 0.08) {
    const cVerts = getCarHullVertices(car);
    for (let i = 0; i < bricks.length; i++) {
      const b = bricks[i];
      if (!b.supported) {
        const m = collideCarBrick(car, cVerts, b);
        if (m && m.ny > 0.35) b.supported = true;
      }
    }
  }

  for (let i = 0; i < bricks.length; i++) {
    const b = bricks[i];
    if (b.bonded) continue;

    // Unsupported bricks in mid-air must never sleep
    if (!b.supported) {
      b.sleeping = false;
      b.sleepTimer = 0;
      movingCount++;
      continue;
    }

    if (b.sleeping) continue;

    const speedSq = b.vx * b.vx + b.vy * b.vy;
    const angSpeed = Math.abs(b.omega);

    // Check if supported brick is moving perceptibly
    if (speedSq > 0.008 || angSpeed > 0.16) {
      movingCount++;
      b.sleepTimer = 0;
    } else {
      b.sleepTimer += FIXED_DT;
      // Gently damp micro-oscillations once nearly at rest on a support
      b.vx *= 0.72;
      b.vy *= 0.72;
      b.omega *= 0.68;
      if (b.sleepTimer > 0.25) {
        b.vx = 0;
        b.vy = 0;
        b.omega = 0;
        b.sleeping = true;
      }
    }
  }

  const carMoving = Math.abs(car.vx) > 0.05 || Math.abs(car.vy) > 0.05;
  if (movingCount === 0 && !carMoving && simTime > 0.4) {
    settledTimer += FIXED_DT;
    if (settledTimer > 0.30) {
      car.vx = 0;
      car.vy = 0;
      car.omega = 0;
      simState = "settled";
      updateStatusUI("settled");
    }
  } else {
    settledTimer = 0;
  }
}

