// Mark bricks resting on the ground or on the stopped car as base-supported
const carStopped = Math.abs(car.vx) < 0.08;
const cVerts = carStopped ? getCarHullVertices(car) : null;

for (let i = 0; i < bricks.length; i++) {
  const b = bricks[i];
  if (b.bonded) {
    b.supported = true;
    continue;
  }
  const minY = b.y - (Math.abs(b.sin) * b.hw + Math.abs(b.cos) * b.hh);
  let sup = (minY <= 0.015);
  if (!sup && carStopped) {
    const m = collideCarBrick(car, cVerts, b);
    if (m && m.ny > 0.30) sup = true;
  }
  b.supported = sup;
}

// Propagate vertical support upward through resting brick piles (up to 16 courses tall)
for (let pass = 0; pass < 10; pass++) {
  let changed = false;
  for (let l = 0; l < bricksByLayer.length; l++) {
    const layerBricks = bricksByLayer[l];
    const n = layerBricks.length;
    for (let i = 0; i < n; i++) {
      const a = layerBricks[i];
      for (let j = i + 1; j < n; j++) {
        const b = layerBricks[j];
        if (a.supported === b.supported) continue;
        if (Math.abs(b.x - a.x) > 0.54 || Math.abs(b.y - a.y) > 0.54) continue;
        const m = collideBrickBrick(a, b);
        if (m && m.depth > 0.0001) {
          if (a.supported && m.ny > 0.30) { b.supported = true; changed = true; }
          else if (b.supported && m.ny < -0.30) { a.supported = true; changed = true; }
        }
      }
    }
  }
  if (!changed) break;
}

