  }
  b.supported = sup;
}

// Propagate vertical support upward through resting brick piles (up to 16 courses tall)
for (let pass = 0; pass < 10; pass++) {
  let changed = false;
  for (let l = 0; l < bricksByLayer.length; l++) {
