args.streamContent:
// Car-Brick overlap projection
const carStopped = Math.abs(car.vx) < 0.08 && Math.abs(car.vy) < 0.08;
const updatedCarVerts = getCarHullVertices(car);
for (let i = 0; i < bricks.length; i++) {
  const b = bricks[i];
  if (b.sleeping && carStopped) continue;
  const m = collideCarBrick(car, updatedCarVerts, b);
  if (m && m.depth > 0.001) {
    const corr = (m.depth - 0.0005) * 0.78;
    if (b.bonded) {
      // Intact wall pushes car back
      car.x -= m.nx * corr;
      car.y -= Math.max(0, m.ny * corr * 0.25);
    } else {
      const totalInv = car.invMass + b.invMass;
      const carShare = car.invMass / totalInv;
      const brickShare = b.invMass / totalInv;
      car.x -= m.nx * corr * carShare;
      car.y -= Math.max(0, m.ny * corr * carShare);
      b.x += m.nx * corr * brickShare;
      b.y += m.ny * corr * brickShare;
    }
  }
}

