  // Find contact points on brick (support edge clipped against car hull along tangent)
  const edgeB = getSupportEdge(brickVerts, -bestNx, -bestNy);
  const tx = -bestNy;
  const ty = bestNx;

  let minCarT = Infinity, maxCarT = -Infinity;
  for (let i = 0; i < numCarVerts; i++) {
    const t = carVerts[i].x * tx + carVerts[i].y * ty;
    if (t < minCarT) minCarT = t;
    if (t > maxCarT) maxCarT = t;
  }

  const tB0 = edgeB[0].x * tx + edgeB[0].y * ty;
  const tB1 = edgeB[1].x * tx + edgeB[1].y * ty;
  const clipT0 = Math.max(minCarT, Math.min(tB0, tB1));
  const clipT1 = Math.min(maxCarT, Math.max(tB0, tB1));

  const contacts = [];
  if (clipT1 >= clipT0 - 0.005) {
    contacts.push(sampleEdgeAtTangent(edgeB, tB0, tB1, clipT0));
    if (clipT1 - clipT0 > 0.008) {
      contacts.push(sampleEdgeAtTangent(edgeB, tB0, tB1, clipT1));
    }
  } else {
    contacts.push({ x: edgeB[0].x, y: edgeB[0].y });
  }

  return {
    nx: bestNx,
    ny: bestNy,
    depth: minOverlap,
    contacts: contacts
  };
}

