for (let l = 0; l < bricksByLayer.length; l++) {
  const layerBricks = bricksByLayer[l];
  const n = layerBricks.length;
  for (let i = 0; i < n; i++) {
    const a = layerBricks[i];
    for (let j = i + 1; j < n; j++) {
      const b = layerBricks[j];
      if (a.supported === b.supported) continue;
      if (Math.abs(b.x - a.x) > 0.54 || Math.abs(b.y - a.y) > 0.54) continue;
      const m = collideBrickBrick(a, b);
      if (m && m.depth >= -0.002) {
        if (a.supported && m.ny > 0.30) { b.supported = true; changed = true; }
        else if (b.supported && m.ny < -0.30) { a.supported = true; changed = true; }
      }
    }
  }
}

