args.streamContent:
for (let i = 0; i < bricks.length; i++) {
  const b = bricks[i];
  if (b.bonded || b.sleeping) continue;

  const speedSq = b.vx * b.vx + b.vy * b.vy;
  const angSpeed = Math.abs(b.omega);

  // Check if brick is moving perceptibly
  if (speedSq > 0.008 || angSpeed > 0.16) {
    movingCount++;
    b.sleepTimer = 0;
  } else {
    b.sleepTimer += FIXED_DT;
    // Gently damp micro-oscillations once nearly at rest
    b.vx *= 0.72;
    b.vy *= 0.72;
    b.omega *= 0.68;
    if (b.sleepTimer > 0.25) {
      b.vx = 0;
      b.vy = 0;
      b.omega = 0;
      b.sleeping = true;
    }
  }
}

const carMoving = Math.abs(car.vx) > 0.04 || Math.abs(car.vy) > 0.04 || Math.abs(car.omega) > 0.04;
if (movingCount === 0 && !carMoving && simTime > 0.4) {
  settledTimer += FIXED_DT;
  if (settledTimer > 0.25) {
    car.vx = 0;
    car.vy = 0;
    car.omega = 0;
    simState = "settled";
    updateStatusUI("settled");
  }
} else {
  settledTimer = 0;
}

for (let i = 0; i < bricks.length; i++) {
  const b = bricks[i];
  if (b.bonded || b.sleeping) continue;

  const speedSq = b.vx * b.vx + b.vy * b.vy;
  const angSpeed = Math.abs(b.omega);

  // Check if brick is moving perceptibly
  if (speedSq > 0.008 || angSpeed > 0.16) {
    movingCount++;
    b.sleepTimer = 0;
  } else {
    b.sleepTimer += FIXED_DT;
    // Gently damp micro-oscillations once nearly at rest
    b.vx *= 0.72;
    b.vy *= 0.72;
    b.omega *= 0.68;
    if (b.sleepTimer > 0.25) {
      b.vx = 0;
      b.vy = 0;
      b.omega = 0;
      b.sleeping = true;
    }
  }
}

