function getMovingBricksCount() {
  if (!impactOccurred) return 0;
  let count = 0;
  for (let i = 0; i < bricks.length; i++) {
    const b = bricks[i];
    if (!b.bonded && !b.sleeping && (b.vx * b.vx + b.vy * b.vy > 0.008 || Math.abs(b.omega) > 0.16)) {
      count++;
    }
  }
  return count;
}

function getMovingBricksCount() {
  if (!impactOccurred) return 0;
  let count = 0;
  for (let i = 0; i < bricks.length; i++) {
    const b = bricks[i];
    if (!b.bonded && !b.sleeping && (b.vx * b.vx + b.vy * b.vy > 0.008 || Math.abs(b.omega) > 0.16)) {
      count++;
    }
  }
  return count;
}

