// =========================================================================
const FIXED_DT = 1 / 60;
const SUBSTEPS = 8;
const SUB_DT = FIXED_DT / SUBSTEPS;
const SOLVER_ITERATIONS = 10;

const TRACK_START_X = 0.75; // left margin in meters
const RUNWAY_GAP = 3.25;    // distance from front bumper to wall front face in meters

let simState = "ready"; // "ready" | "running" | "settled"
let simTime = 0;
let impactOccurred = false;
let settledTimer = 0;
let peakGForce = 0;
let totalMomentumTransferred = 0;
let cameraShake = 0;
let cameraX = 0;

let car = null;
let bricks = [];
let bricksByLayer = [];
let mortarJoints = [];
let depthCouplings = [];

// Visual-only effects
let dustParticles = [];
let skidMarks = [];

// =========================================================================
// INITIALIZE / RESET SCENE
// =========================================================================
function createCar() {
  const w = DEFAULTS.carWidth;
  const h = DEFAULTS.carHeight;
  const m = DEFAULTS.carMass;
  const inertia = (m * (w * w + h * h)) / 12;

  const startCenterX = TRACK_START_X + w * 0.5;
  const restCenterY = h * 0.5;

  return {
    x: startCenterX,
    y: restCenterY,
    vx: 0,
    vy: 0,
    angle: 0,
    omega: 0,
    w: w,
    h: h,
    hw: w * 0.5,
    hh: h * 0.5,
    mass: m,
    invMass: 1 / m,
    inertia: inertia,
    invInertia: 1 / inertia,
    targetSpeed: settings.carSpeed,
    wheelAngle: 0,
    crumple: 0,
    airbagDeployed: false,
    dummyPitch: 0,
    dummyPitchVel: 0,
    prevVx: 0
  };
}

function getCarHullVertices(c) {
  // Aerodynamic sedan convex hull in local coordinates around (c.x, c.y)
  // Total width = 4.2m (-2.1 to +2.1), total height = 1.45m (-0.725 to +0.725)
  const hw = c.hw;
  const hh = c.hh;
  const crumple = c.crumple;
  const frontX = hw - crumple;
  const hoodTopY = -hh + 0.86 + crumple * 0.18;

  const localPts = [
    { x: -hw,          y: -hh + 0.05 }, // 0: rear bottom
    { x: frontX - 0.06, y: -hh + 0.03 }, // 1: front air-dam bottom (3cm clearance engages row 0)
    { x: frontX,       y: -hh + 0.22 }, // 2: front bumper nose
    { x: frontX - 0.04, y: hoodTopY   }, // 3: hood leading edge
    { x: 0.72,         y: hh         }, // 4: windshield top / roof front
    { x: -0.95,        y: hh         }, // 5: roof rear
    { x: -hw,          y: -hh + 0.92 }  // 6: rear decklid / trunk
  ];

  const cos = Math.cos(c.angle);
  const sin = Math.sin(c.angle);
  const worldPts = new Array(localPts.length);
  for (let i = 0; i < localPts.length; i++) {
    const lx = localPts[i].x;
    const ly = localPts[i].y;
    worldPts[i] = {
      x: c.x + lx * cos - ly * sin,
      y: c.y + lx * sin + ly * cos
    };
  }
  return worldPts;
}

function createWall() {
  bricks = [];
  bricksByLayer = [];
  mortarJoints = [];
  depthCouplings = [];

  const cols = settings.wallColumns;
  const rows = settings.wallRows;
  const layers = settings.wallDepthLayers;
  const bw = DEFAULTS.brickWidth;
  const bh = DEFAULTS.brickHeight;
  const bm = settings.brickMass;
  const bInertia = (bm * (bw * bw + bh * bh)) / 12;

  const wallFrontX = TRACK_START_X + DEFAULTS.carWidth + RUNWAY_GAP;
  // Overlapping depth layers offset slightly in X so additional layers physically thicken the wall barrier
  const layerStepX = layers > 1 ? 0.09 : 0;

  let idCounter = 0;
  const grid = [];

  for (let l = 0; l < layers; l++) {
    const layerArr = [];
    const layerGrid = [];
    const layerOffsetX = l * layerStepX;

    for (let r = 0; r < rows; r++) {
      const rowGrid = [];
      // Running bond: alternating seams between even and odd rows
      // Layer parity also alternates seam alignment across wythes like real Flemish/English bond
      const isStaggeredRow = ((r + l) % 2) === 1;
      const staggerX = isStaggeredRow ? (bw * 0.5) : 0;

      for (let c = 0; c < cols; c++) {
        const cx = wallFrontX + layerOffsetX + staggerX + c * bw + bw * 0.5;
        const cy = r * bh + bh * 0.5;

        // Deterministic terracotta shade variation per (l, r, c)
        const hash = ((l * 131 + r * 37 + c * 17) & 0xff) / 255;

        const brick = {
          id: idCounter++,
          layer: l,
          row: r,
          col: c,
          x: cx,
          y: cy,
          initialX: cx,
          initialY: cy,
          vx: 0,
          vy: 0,
          angle: 0,
          omega: 0,
          cos: 1,
          sin: 0,
          w: bw,
          h: bh,
          hw: bw * 0.5,
          hh: bh * 0.5,
          mass: bm,
          invMass: 1 / bm,
          inertia: bInertia,
          invInertia: 1 / bInertia,
          shade: hash,
          bonded: true,
          stressAccum: 0,
          supportsBelow: [],
          neighbors: [],
          sleepTimer: 0,
          sleeping: false
        };

        bricks.push(brick);
        layerArr.push(brick);
        rowGrid.push(brick);
      }
      layerGrid.push(rowGrid);
    }
    bricksByLayer.push(layerArr);
    grid.push(layerGrid);
  }

  // Link structural support hierarchy (bricks below in row - 1) and cohesive mortar joints
  for (let l = 0; l < layers; l++) {
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const bA = grid[l][r][c];

        // Horizontal neighbor in same row
        if (c + 1 < cols) {
          const bB = grid[l][r][c + 1];
          addMortarJoint(bA, bB, 1.0);
        }

        // Vertical neighbors in row above
        if (r + 1 < rows) {
          for (let cAbove = 0; cAbove < cols; cAbove++) {
            const bAbove = grid[l][r + 1][cAbove];
            const dx = Math.abs(bAbove.x - bA.x);
            if (dx < bw * 0.78) {
              bAbove.supportsBelow.push(bA);
              addMortarJoint(bA, bAbove, 1.15);
            }
          }
        }
      }
    }
  }

  // Create inter-layer tie couplings between overlapping wythes (depth layers)
  for (let l = 0; l < layers - 1; l++) {
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const bFront = grid[l][r][c];
        const bBack = grid[l + 1][r][c];
        depthCouplings.push({
          a: bFront,
          b: bBack,
          dx0: bBack.x - bFront.x,
          dy0: bBack.y - bFront.y,
          broken: false
        });
        bFront.neighbors.push(bBack);
        bBack.neighbors.push(bFront);
      }
    }
  }
}

function addMortarJoint(a, b, strengthFactor) {
  mortarJoints.push({
    a: a,
    b: b,
    dx0: b.x - a.x,
    dy0: b.y - a.y,
    strength: strengthFactor,
    broken: false
  });
  a.neighbors.push(b);
  b.neighbors.push(a);
}

function resetExperiment() {
  resetVisualRNG();
  simState = "ready";
  simTime = 0;
  impactOccurred = false;
  settledTimer = 0;
  peakGForce = 0;
  totalMomentumTransferred = 0;
  cameraShake = 0;
  cameraX = 0;
  dustParticles = [];
  skidMarks = [];

  car = createCar();
  createWall();
  updateStatusUI("ready");
  updateTelemetryUI();
}

function startExperiment() {
  resetExperiment();
  simState = "running";
  // Launch car from left toward wall; reaches target speed rapidly on the approach track
  car.vx = settings.carSpeed;
  car.prevVx = car.vx;
  updateStatusUI("running");
  updateTelemetryUI();
}

// =========================================================================
// RIGID-BODY COLLISION DETECTION (2D SAT FOR OBB & CONVEX HULL)
// =========================================================================
function updateBrickTransform(b) {
  b.cos = Math.cos(b.angle);
  b.sin = Math.sin(b.angle);
}

function getBrickVertices(b) {
  const wx = b.cos * b.hw;
  const wy = b.sin * b.hw;
  const hx = -b.sin * b.hh;
  const hy = b.cos * b.hh;
  return [
    { x: b.x - wx - hx, y: b.y - wy - hy },
    { x: b.x + wx - hx, y: b.y + wy - hy },
    { x: b.x + wx + hx, y: b.y + wy + hy },
    { x: b.x - wx + hx, y: b.y - wy + hy }
  ];
}

// SAT between two brick OBBs A and B
function collideBrickBrick(a, b) {
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  // Bounding circle radius of 0.50x0.24 brick is sqrt(0.25^2 + 0.12^2) = 0.2773m
  // Max center distance is 0.5546m -> distSq > 0.308
  if (dx * dx + dy * dy > 0.308) return null;

  const axesX = [a.cos, -a.sin, b.cos, -b.sin];
  const axesY = [a.sin,  a.cos, b.sin,  b.cos];

  let minOverlap = Infinity;
  let bestAxisX = 0;
  let bestAxisY = 0;

  for (let i = 0; i < 4; i++) {
    const ax = axesX[i];
    const ay = axesY[i];

    const rA = a.hw * Math.abs(ax * a.cos + ay * a.sin) +
               a.hh * Math.abs(-ax * a.sin + ay * a.cos);
    const rB = b.hw * Math.abs(ax * b.cos + ay * b.sin) +
               b.hh * Math.abs(-ax * b.sin + ay * b.cos);

    const dist = dx * ax + dy * ay;
    const overlap = rA + rB - Math.abs(dist);
    if (overlap < -0.002) return null;

    if (overlap < minOverlap) {
      minOverlap = overlap;
      if (dist < 0) {
        bestAxisX = -ax;
        bestAxisY = -ay;
      } else {
        bestAxisX = ax;
        bestAxisY = ay;
      }
    }
  }

  // Find the support edge on A (along +normal) and on B (along -normal) and clip along tangent
  const vertsA = getBrickVertices(a);
  const vertsB = getBrickVertices(b);

  const edgeA = getSupportEdge(vertsA, bestAxisX, bestAxisY);
  const edgeB = getSupportEdge(vertsB, -bestAxisX, -bestAxisY);

  const tx = -bestAxisY;
  const ty = bestAxisX;

  const tA0 = edgeA[0].x * tx + edgeA[0].y * ty;
  const tA1 = edgeA[1].x * tx + edgeA[1].y * ty;
  const tB0 = edgeB[0].x * tx + edgeB[0].y * ty;
  const tB1 = edgeB[1].x * tx + edgeB[1].y * ty;

  const minTA = Math.min(tA0, tA1), maxTA = Math.max(tA0, tA1);
  const minTB = Math.min(tB0, tB1), maxTB = Math.max(tB0, tB1);

  const clipT0 = Math.max(minTA, minTB);
  const clipT1 = Math.min(maxTA, maxTB);

  const contacts = [];
  if (clipT1 >= clipT0 - 0.005) {
    const p0 = sampleEdgeAtTangent(edgeB, tB0, tB1, clipT0);
    contacts.push(p0);
    if (clipT1 - clipT0 > 0.008) {
      const p1 = sampleEdgeAtTangent(edgeB, tB0, tB1, clipT1);
      contacts.push(p1);
    }
  } else {
    contacts.push({
      x: (edgeA[0].x + edgeB[0].x) * 0.5,
      y: (edgeA[0].y + edgeB[0].y) * 0.5
    });
  }

  return {
    nx: bestAxisX,
    ny: bestAxisY,
    depth: minOverlap,
    contacts: contacts
  };
}

function getSupportEdge(verts, nx, ny) {
  let bestIdx = 0;
  let bestDot = -Infinity;
  for (let i = 0; i < 4; i++) {
    const d = verts[i].x * nx + verts[i].y * ny;
    if (d > bestDot) {
      bestDot = d;
      bestIdx = i;
    }
  }
  const prevIdx = (bestIdx + 3) % 4;
  const nextIdx = (bestIdx + 1) % 4;
  const dPrev = verts[prevIdx].x * nx + verts[prevIdx].y * ny;
  const dNext = verts[nextIdx].x * nx + verts[nextIdx].y * ny;
  if (dPrev > dNext) {
    return [verts[prevIdx], verts[bestIdx]];
  }
  return [verts[bestIdx], verts[nextIdx]];
}

function sampleEdgeAtTangent(edge, t0, t1, t) {
  const span = t1 - t0;
  if (Math.abs(span) < 1e-6) {
    return { x: edge[0].x, y: edge[0].y };
  }
  const u = Math.max(0, Math.min(1, (t - t0) / span));
  return {
    x: edge[0].x + (edge[1].x - edge[0].x) * u,
    y: edge[0].y + (edge[1].y - edge[0].y) * u
  };
}

// SAT between Car Convex Hull and Brick OBB
function collideCarBrick(c, carVerts, b) {
  const dx = b.x - c.x;
  const dy = b.y - c.y;
  if (Math.abs(dx) > c.hw + 0.45 || Math.abs(dy) > c.hh + 0.45) return null;

  const brickVerts = getBrickVertices(b);

  let minOverlap = Infinity;
  let bestNx = 0;
  let bestNy = 0;

  // Test Car polygon edge normals + Brick OBB axes
  const numCarVerts = carVerts.length;
  const totalAxes = numCarVerts + 2;

  for (let i = 0; i < totalAxes; i++) {
    let ax, ay;
    if (i < numCarVerts) {
      const p0 = carVerts[i];
      const p1 = carVerts[(i + 1) % numCarVerts];
      const ex = p1.x - p0.x;
      const ey = p1.y - p0.y;
      const len = Math.hypot(ex, ey);
      if (len < 1e-6) continue;
      ax = ey / len;
      ay = -ex / len;
    } else if (i === numCarVerts) {
      ax = b.cos;
      ay = b.sin;
    } else {
      ax = -b.sin;
      ay = b.cos;
    }

    let minA = Infinity, maxA = -Infinity;
    for (let j = 0; j < numCarVerts; j++) {
      const proj = carVerts[j].x * ax + carVerts[j].y * ay;
      if (proj < minA) minA = proj;
      if (proj > maxA) maxA = proj;
    }

    let minB = Infinity, maxB = -Infinity;
    for (let j = 0; j < 4; j++) {
      const proj = brickVerts[j].x * ax + brickVerts[j].y * ay;
      if (proj < minB) minB = proj;
      if (proj > maxB) maxB = proj;
    }

    const overlap = Math.min(maxA, maxB) - Math.max(minA, minB);
    if (overlap <= 0) return null;

    if (overlap < minOverlap) {
      minOverlap = overlap;
      const centerDiff = dx * ax + dy * ay;
      if (centerDiff < 0) {
        bestNx = -ax;
        bestNy = -ay;
      } else {
        bestNx = ax;
        bestNy = ay;
      }
    }
  }

  // Find contact points on brick (support edge clipped against car hull along tangent)
  const edgeB = getSupportEdge(brickVerts, -bestNx, -bestNy);
  const tx = -bestNy;
  const ty = bestNx;

  let minCarT = Infinity, maxCarT = -Infinity;
  for (let i = 0; i < numCarVerts; i++) {
    const t = carVerts[i].x * tx + carVerts[i].y * ty;
    if (t < minCarT) minCarT = t;
    if (t > maxCarT) maxCarT = t;
  }

  const tB0 = edgeB[0].x * tx + edgeB[0].y * ty;
  const tB1 = edgeB[1].x * tx + edgeB[1].y * ty;
  const clipT0 = Math.max(minCarT, Math.min(tB0, tB1));
  const clipT1 = Math.min(maxCarT, Math.max(tB0, tB1));

  const contacts = [];
  if (clipT1 >= clipT0 - 0.005) {
    contacts.push(sampleEdgeAtTangent(edgeB, tB0, tB1, clipT0));
    if (clipT1 - clipT0 > 0.008) {
      contacts.push(sampleEdgeAtTangent(edgeB, tB0, tB1, clipT1));
    }
  } else {
    contacts.push({ x: edgeB[0].x, y: edgeB[0].y });
  }

  return {
    nx: bestNx,
    ny: bestNy,
    depth: minOverlap,
    contacts: contacts
  };
}

// =========================================================================
// IMPULSE RESOLUTION
// =========================================================================
function resolveTwoBodyContact(a, b, cx, cy, nx, ny, depth, restitution, friction, isCarImpact) {
  const aBonded = Boolean(a.bonded);
  const bBonded = Boolean(b.bonded);
  if ((aBonded || a.sleeping) && (bBonded || b.sleeping)) return 0;

  const rAx = cx - a.x;
  const rAy = cy - a.y;
  const rBx = cx - b.x;
  const rBy = cy - b.y;

  const vAx = a.vx - a.omega * rAy;
  const vAy = a.vy + a.omega * rAx;
  const vBx = b.vx - b.omega * rBy;
  const vBy = b.vy + b.omega * rBx;

  const rvx = vBx - vAx;
  const rvy = vBy - vAy;

  const velAlongNormal = rvx * nx + rvy * ny;

  // Wake sleeping brick only if real impact velocity exceeds threshold
  if (a.sleeping && -velAlongNormal > 0.42) { a.sleeping = false; a.sleepTimer = 0; }
  if (b.sleeping && -velAlongNormal > 0.42) { b.sleeping = false; b.sleepTimer = 0; }

  const aStatic = aBonded || Boolean(a.sleeping);
  const bStatic = bBonded || Boolean(b.sleeping);
  if (aStatic && bStatic) return 0;

  // If a brick is still bonded to the coherent masonry wall, its effective structural resistance
  // includes the intact courses backing it in its row
  const behindCols = bBonded ? Math.max(1, settings.wallColumns - b.col) : 1;
  const structuralMult = bBonded ? (1 + 0.18 * behindCols * Math.sqrt(settings.wallDepthLayers)) : 1;

  const invMassA = aStatic ? 0 : a.invMass;
  const invInertiaA = aStatic ? 0 : a.invInertia;
  const invMassB = bBonded ? (b.invMass / structuralMult) : (bStatic ? 0 : b.invMass);
  const invInertiaB = bStatic ? 0 : b.invInertia;

  const rACrossN = rAx * ny - rAy * nx;
  const rBCrossN = rBx * ny - rBy * nx;
  const invMassSum = invMassA + invMassB +
                     rACrossN * rACrossN * invInertiaA +
                     rBCrossN * rBCrossN * invInertiaB;
  if (invMassSum <= 0) return 0;

  // Pure velocity constraint in velocity solver (positional overlap is resolved in NGS position pass without polluting velocity)
  let e = (-velAlongNormal > 0.85) ? restitution : 0;
  let jn = (-(1 + e) * velAlongNormal) / invMassSum;
  if (jn < 0) jn = 0;

  if (jn > 0) {
    const impulseX = jn * nx;
    const impulseY = jn * ny;

    if (!aStatic) {
      a.vx -= impulseX * invMassA;
      a.vy -= impulseY * invMassA;
      a.omega -= (rAx * impulseY - rAy * impulseX) * invInertiaA;
    } else if (aBonded) {
      applyStressToBondedBrick(a, -impulseX, -impulseY, cx, cy);
    }

    if (!bStatic) {
      b.vx += impulseX * invMassB;
      b.vy += impulseY * invMassB;
      b.omega += (rBx * impulseY - rBy * impulseX) * invInertiaB;
    } else if (bBonded) {
      applyStressToBondedBrick(b, impulseX, impulseY, cx, cy);
    }
  }

  // Recompute relative velocity for friction impulse
  const vAx2 = a.vx - a.omega * rAy;
  const vAy2 = a.vy + a.omega * rAx;
  const vBx2 = b.vx - b.omega * rBy;
  const vBy2 = b.vy + b.omega * rBx;
  const rvx2 = vBx2 - vAx2;
  const rvy2 = vBy2 - vAy2;

  const tx = -ny;
  const ty = nx;
  const vt = rvx2 * tx + rvy2 * ty;

  const rACrossT = rAx * ty - rAy * tx;
  const rBCrossT = rBx * ty - rBy * tx;
  const invMassTangent = invMassA + invMassB +
                         rACrossT * rACrossT * invInertiaA +
                         rBCrossT * rBCrossT * invInertiaB;

  if (invMassTangent > 0) {
    let jt = -vt / invMassTangent;

    const restingLoad = (depth > 0.001) ? (Math.min(a.mass, b.mass) * DEFAULTS.gravity * SUB_DT / SOLVER_ITERATIONS) : 0;
    const maxFriction = (jn + restingLoad) * friction;
    if (jt > maxFriction) jt = maxFriction;
    if (jt < -maxFriction) jt = -maxFriction;

    const fImpulseX = jt * tx;
    const fImpulseY = jt * ty;

    if (!aStatic) {
      a.vx -= fImpulseX * invMassA;
      a.vy -= fImpulseY * invMassA;
      a.omega -= (rAx * fImpulseY - rAy * fImpulseX) * invInertiaA;
    }
    if (!bStatic) {
      b.vx += fImpulseX * invMassB;
      b.vy += fImpulseY * invMassB;
      b.omega += (rBx * fImpulseY - rBy * fImpulseX) * invInertiaB;
    }
  }

  return jn;
}

function resolveBrickGround(b) {
  const verts = getBrickVertices(b);
  const e = DEFAULTS.brickRestitution * 0.5;
  const mu = DEFAULTS.groundFriction;

  for (let i = 0; i < 4; i++) {
    const v = verts[i];
    if (v.y <= 0.002) {
      const rx = v.x - b.x;
      const ry = v.y - b.y;

      const vx = b.vx - b.omega * ry;
      const vy = b.vy + b.omega * rx;

      const rCrossN = rx; // normal is (0, 1)
      const kN = b.invMass + rCrossN * rCrossN * b.invInertia;

      const effE = (-vy > 0.9) ? e : 0;
      let jn = (vy < 0) ? (-(1 + effE) * vy) / kN : (b.mass * DEFAULTS.gravity * SUB_DT * 0.5);
      if (jn > 0) {
        if (vy < 0) {
          b.vy += jn * b.invMass;
          b.omega += rx * jn * b.invInertia;
        }

        // Ground friction along tangent (1, 0)
        const vx2 = b.vx - b.omega * ry;
        const rCrossT = -ry;
        const kT = b.invMass + rCrossT * rCrossT * b.invInertia;
        let jt = -vx2 / kT;
        const maxF = jn * mu;
        if (jt > maxF) jt = maxF;
        if (jt < -maxF) jt = -maxF;

        b.vx += jt * b.invMass;
        b.omega += (-ry * jt) * b.invInertia;
      }
    }
  }
}

// =========================================================================
// MORTAR FRACTURE & STRUCTURAL SUPPORT SOLVER
// =========================================================================
function getBrickFractureThreshold(b) {
  const overburden = settings.wallRows - b.row;
  const depthFactor = 0.75 + 0.22 * settings.wallDepthLayers;
  return b.mass * (0.95 + 0.22 * overburden * DEFAULTS.brickFriction) * depthFactor;
}

function unbondBrick(b, impulseX, impulseY, omegaKick) {
  if (!b.bonded) return;
  b.bonded = false;
  b.sleeping = false;
  b.sleepTimer = 0;
  b.vx += impulseX * b.invMass;
  b.vy += impulseY * b.invMass;
  b.omega += omegaKick || 0;

  if (dustParticles.length < 280 && nextVisualRand() < 0.55) {
    spawnDust(b.x, b.y, 2);
  }
}

function applyStressToBondedBrick(b, jx, jy, cx, cy) {
  const jMag = Math.hypot(jx, jy);
  if (jMag <= 0) return;

  // Accumulate physical impulse stress (scaled by solver iterations)
  const stressDelta = jMag / SOLVER_ITERATIONS;
  b.stressAccum += stressDelta;

  // Share part of compressive stress with immediate horizontal neighbor in same row
  const nbrs = b.neighbors;
  for (let i = 0; i < nbrs.length; i++) {
    const nb = nbrs[i];
    if (nb.bonded && nb.layer === b.layer && nb.row === b.row && nb.col > b.col) {
      nb.stressAccum += stressDelta * 0.42;
    }
  }

  const crit = getBrickFractureThreshold(b);
  if (b.stressAccum >= crit) {
    const rx = cx - b.x;
    const ry = cy - b.y;
    const torqueImpulse = (rx * jy - ry * jx) * b.invInertia * 0.45;
    unbondBrick(b, jx * 0.65, jy * 0.65, torqueImpulse);
  }
}

function updateWallStructuralSupport() {
  // Sweep from bottom row up: if supporting bricks below a bonded brick have displaced, it loses support and falls
  for (let l = 0; l < bricksByLayer.length; l++) {
    const layerBricks = bricksByLayer[l];
    for (let i = 0; i < layerBricks.length; i++) {
      const b = layerBricks[i];
      if (!b.bonded) continue;

      // Decay sub-critical elastic stress
      b.stressAccum *= 0.92;

      if (b.row > 0) {
        const supports = b.supportsBelow;
        let validSupports = 0;
        let leftSupportGone = false;
        let rightSupportGone = false;

        for (let s = 0; s < supports.length; s++) {
          const sup = supports[s];
          const supDisplaced = !sup.bonded &&
            (Math.abs(sup.x - sup.initialX) > 0.055 || Math.abs(sup.y - sup.initialY) > 0.035);
          if (!supDisplaced) {
            validSupports++;
          } else {
            if (sup.initialX <= b.initialX) leftSupportGone = true;
            if (sup.initialX >= b.initialX) rightSupportGone = true;
          }
        }

        // If supports underneath have been knocked away, brick unbonds and falls under gravity
        if (validSupports === 0 || (supports.length >= 2 && validSupports === 1 && b.stressAccum > getBrickFractureThreshold(b) * 0.45)) {
          const toppleOmega = leftSupportGone && !rightSupportGone ? 1.35 : (rightSupportGone && !leftSupportGone ? -1.35 : 0.25);
          unbondBrick(b, 0, 0, toppleOmega);
        }
      }
    }
  }

  // Inter-layer shear transfer between overlapping wythes (depth layers)
  for (let i = 0; i < depthCouplings.length; i++) {
    const d = depthCouplings[i];
    if (d.broken) continue;
    const a = d.a;
    const b = d.b;
    if (a.bonded && b.bonded) continue;

    const errX = (b.x - a.x) - d.dx0;
    const errY = (b.y - a.y) - d.dy0;
    if (Math.hypot(errX, errY) > 0.14) {
      d.broken = true;
      continue;
    }

    // Transfer shear force between front wythe and back wythe before collar joint shears
    const shearX = (b.vx - a.vx) * 0.12 * a.mass;
    const shearY = (b.vy - a.vy) * 0.12 * a.mass;
    if (!a.bonded && !b.bonded) {
      a.vx += shearX * a.invMass;
      a.vy += shearY * a.invMass;
      b.vx -= shearX * b.invMass;
      b.vy -= shearY * b.invMass;
    } else if (!a.bonded && b.bonded) {
      applyStressToBondedBrick(b, -shearX * 3.5, -shearY * 3.5, b.x, b.y);
    } else if (a.bonded && !b.bonded) {
      applyStressToBondedBrick(a, shearX * 3.5, shearY * 3.5, a.x, a.y);
    }
  }
}

function spawnDust(wx, wy, count) {
  for (let i = 0; i < count; i++) {
    const ang = nextVisualRand() * Math.PI * 2;
    const spd = 0.4 + nextVisualRand() * 3.2;
    const isChip = nextVisualRand() < 0.35;
    dustParticles.push({
      x: wx + (nextVisualRand() - 0.5) * 0.14,
      y: Math.max(0.03, wy + (nextVisualRand() - 0.5) * 0.14),
      vx: Math.cos(ang) * spd + (car ? car.vx * 0.18 : 0),
      vy: Math.abs(Math.sin(ang)) * spd + 0.5,
      size: isChip ? (2.5 + nextVisualRand() * 3.5) : (8 + nextVisualRand() * 14),
      alpha: isChip ? 0.9 : 0.42,
      life: 0,
      maxLife: isChip ? (0.45 + nextVisualRand() * 0.5) : (0.55 + nextVisualRand() * 0.65),
      isChip: isChip
    });
  }
}

// =========================================================================
// PHYSICS STEP (SUB-STEPPED DETERMINISTIC SOLVER)
// =========================================================================
function stepPhysics() {
  if (simState !== "running") return;

  const g = DEFAULTS.gravity;
  const groundMu = DEFAULTS.groundFriction;
  const brickMu = DEFAULTS.brickFriction;
  const brickRest = DEFAULTS.brickRestitution;

  for (let sub = 0; sub < SUBSTEPS; sub++) {
    simTime += SUB_DT;
    car.prevVx = car.vx;

    // 1. Update Car Integration & Suspension
    if (!impactOccurred) {
      // Maintain exact configured test speed on approach track until impact
      car.vx = settings.carSpeed;
      car.vy = 0;
      car.angle = 0;
      car.omega = 0;
    } else {
      // Post-impact: gravity + two-axle spring-damper suspension + ground braking friction
      car.vy -= g * SUB_DT;

      const restY = car.hh;
      const yErr = restY - car.y;
      // Suspension vertical spring + damper
      const kSpring = 48.0;
      const cDamp = 11.5;
      if (car.y <= restY + 0.08) {
        car.vy += (yErr * kSpring - car.vy * cDamp) * SUB_DT;
      }

      // Pitch suspension restoring torque (front & rear axles resist pitch)
      const kPitch = 65.0;
      const cPitch = 12.0;
      car.omega += (-car.angle * kPitch - car.omega * cPitch) * SUB_DT;
      car.angle = Math.max(-0.22, Math.min(0.22, car.angle));

      // Ground tire/chassis friction when in contact with ground
      if (car.y <= restY + 0.04) {
        const decel = groundMu * g * SUB_DT;
        if (Math.abs(car.vx) <= decel) {
          car.vx = 0;
        } else {
          car.vx -= Math.sign(car.vx) * decel;
        }

        // Record skid marks during heavy post-impact braking/deceleration
        if (Math.abs(car.vx) > 0.8 && sub === 0 && skidMarks.length < 300) {
          skidMarks.push({
            x: car.x - 1.25,
            w: Math.max(0.15, Math.abs(car.vx) * FIXED_DT * 1.1),
            alpha: Math.min(0.55, Math.abs(car.vx) / 25)
          });
          skidMarks.push({
            x: car.x + 1.20,
            w: Math.max(0.15, Math.abs(car.vx) * FIXED_DT * 1.1),
            alpha: Math.min(0.55, Math.abs(car.vx) / 25)
          });
        }
      }
    }

    car.x += car.vx * SUB_DT;
    car.y += car.vy * SUB_DT;
    car.angle += car.omega * SUB_DT;

    // Clamp car above ground plane
    if (car.y < car.hh) {
      car.y = car.hh;
      if (car.vy < 0) car.vy = -car.vy * 0.12;
    }

    const wheelRadius = 0.34;
    car.wheelAngle += (car.vx * SUB_DT) / wheelRadius;

    // Check if car has reached the wall proximity to wake physics
    const wallFrontTriggerX = TRACK_START_X + DEFAULTS.carWidth + RUNWAY_GAP - 0.08;
    if (!impactOccurred && (car.x + car.hw) >= wallFrontTriggerX) {
      impactOccurred = true;
    }

    // 2. Integrate Unbonded Bricks (bonded bricks remain in static equilibrium until fractured)
    if (impactOccurred) {
      for (let i = 0; i < bricks.length; i++) {
        const b = bricks[i];
        if (b.bonded || b.sleeping) continue;

        b.vy -= g * SUB_DT;

        // Mild aerodynamic drag & angular damping for physical stability
        b.vx *= 0.9992;
        b.vy *= 0.9992;
        b.omega *= 0.994;

        b.x += b.vx * SUB_DT;

        b.y += b.vy * SUB_DT;
        b.angle += b.omega * SUB_DT;
        updateBrickTransform(b);
      }

      // 3. Update Wall Structural Support & Mortar Cohesion
      updateWallStructuralSupport();

      // 4. Collect Contact Manifolds for Current Substep
      const carVerts = getCarHullVertices(car);
      const carContacts = [];
      for (let i = 0; i < bricks.length; i++) {
        const b = bricks[i];
        if (b.sleeping && Math.abs(car.vx) < 0.08 && Math.abs(car.vy) < 0.08 && Math.abs(car.omega) < 0.05) continue;
        const m = collideCarBrick(car, carVerts, b);
        if (m) {
          b.sleeping = false;
          b.sleepTimer = 0;
          carContacts.push({ brick: b, m: m });
        }
      }

      const brickContacts = [];
      for (let l = 0; l < bricksByLayer.length; l++) {
        const layerBricks = bricksByLayer[l];
        const n = layerBricks.length;
        for (let i = 0; i < n; i++) {
          const bA = layerBricks[i];
          for (let j = i + 1; j < n; j++) {
            const bB = layerBricks[j];
            if ((bA.bonded || bA.sleeping) && (bB.bonded || bB.sleeping)) continue;
            if (Math.abs(bB.x - bA.x) > 0.56 || Math.abs(bB.y - bA.y) > 0.56) continue;
            const m = collideBrickBrick(bA, bB);
            if (m) {
              brickContacts.push({ a: bA, b: bB, m: m });
            }
          }
        }
      }

      // 5. Iterative Sequential Impulse Solver
      let substepCarImpulse = 0;
      for (let iter = 0; iter < SOLVER_ITERATIONS; iter++) {
        // Ground contacts first
        for (let i = 0; i < bricks.length; i++) {
          const b = bricks[i];
          if (!b.bonded && !b.sleeping && b.y < 0.32) {
            resolveBrickGround(b);
          }
        }

        // Alternate sweep order for symmetric force propagation across columns
        if (iter % 2 === 0) {
          for (let i = 0; i < brickContacts.length; i++) {
            const c = brickContacts[i];
            const pts = c.m.contacts;
            for (let k = 0; k < pts.length; k++) {
              resolveTwoBodyContact(
                c.a, c.b,
                pts[k].x, pts[k].y,
                c.m.nx, c.m.ny,
                c.m.depth / pts.length,
                brickRest, brickMu, false
              );
            }
          }
        } else {
          for (let i = brickContacts.length - 1; i >= 0; i--) {
            const c = brickContacts[i];
            const pts = c.m.contacts;
            for (let k = 0; k < pts.length; k++) {
              resolveTwoBodyContact(
                c.a, c.b,
                pts[k].x, pts[k].y,
                c.m.nx, c.m.ny,
                c.m.depth / pts.length,
                brickRest, brickMu, false
              );
            }
          }
        }

        // Car-Brick contacts
        for (let i = 0; i < carContacts.length; i++) {
          const cc = carContacts[i];
          const pts = cc.m.contacts;
          for (let k = 0; k < pts.length; k++) {
            const jn = resolveTwoBodyContact(
              car, cc.brick,
              pts[k].x, pts[k].y,
              cc.m.nx, cc.m.ny,
              cc.m.depth / pts.length,
              brickRest, brickMu * 0.75, true
            );
            substepCarImpulse += jn;
          }
        }
      }

      // Track impact telemetry, front crumple deformation, airbag & camera shake
      if (substepCarImpulse > 0) {
        totalMomentumTransferred += substepCarImpulse;
        const instAccelG = Math.abs(car.vx - car.prevVx) / (SUB_DT * g);
        if (instAccelG > peakGForce) peakGForce = instAccelG;

        // Progressive front crumple zone compression
        const crumpleDelta = Math.min(0.015, substepCarImpulse / 420000);
        car.crumple = Math.min(0.36, car.crumple + crumpleDelta);

        if (substepCarImpulse > 900 && !car.airbagDeployed) {
          car.airbagDeployed = true;
          car.dummyPitchVel = 7.5;
        }

        if (substepCarImpulse > 1800) {
          cameraShake = Math.min(10, cameraShake + substepCarImpulse / 8500);
          if (dustParticles.length < 280 && nextVisualRand() < 0.6) {
            spawnDust(car.x + car.hw - car.crumple, car.y - 0.1, 2);
          }
        }
      }

      // 6. Nonlinear Position Projection (prevents overlap and tunneling)
      for (let pass = 0; pass < 3; pass++) {
        // Brick-Brick overlap projection
        for (let i = 0; i < brickContacts.length; i++) {
          const c = brickContacts[i];
          const a = c.a;
          const b = c.b;
          const aStatic = a.bonded || a.sleeping;
          const bStatic = b.bonded || b.sleeping;
          if (aStatic && bStatic) continue;

          const m = collideBrickBrick(a, b);
          if (m && m.depth > 0.002) {
            const corr = (m.depth - 0.0015) * 0.38;
            const invA = aStatic ? 0 : a.invMass;
            const invB = bStatic ? 0 : b.invMass;
            const totalInv = invA + invB;
            if (totalInv > 0) {
              const shareA = invA / totalInv;
              const shareB = invB / totalInv;
              a.x -= m.nx * corr * shareA;
              a.y -= m.ny * corr * shareA;
              b.x += m.nx * corr * shareB;
              b.y += m.ny * corr * shareB;
              if (!aStatic) { a.vx *= 0.992; a.omega *= 0.985; }
              if (!bStatic) { b.vx *= 0.992; b.omega *= 0.985; }
            }
          }
        }

        // Car-Brick overlap projection
        const carStopped = Math.abs(car.vx) < 0.08 && Math.abs(car.vy) < 0.08;
        const updatedCarVerts = getCarHullVertices(car);
        for (let i = 0; i < bricks.length; i++) {
          const b = bricks[i];
          if (b.sleeping && carStopped) continue;
          const m = collideCarBrick(car, updatedCarVerts, b);
          if (m && m.depth > 0.001) {
            const corr = (m.depth - 0.0005) * 0.78;
            if (b.bonded) {
              // Intact wall pushes car back
              car.x -= m.nx * corr;
              car.y -= Math.max(0, m.ny * corr * 0.25);
            } else {
              const totalInv = car.invMass + b.invMass;
              const carShare = car.invMass / totalInv;
              const brickShare = b.invMass / totalInv;
              car.x -= m.nx * corr * carShare;
              car.y -= Math.max(0, m.ny * corr * carShare);
              b.x += m.nx * corr * brickShare;
              b.y += m.ny * corr * brickShare;
            }
          }
        }

        // Ground clamp for all unbonded bricks
        for (let i = 0; i < bricks.length; i++) {
          const b = bricks[i];
          if (!b.bonded && !b.sleeping && b.y < 0.30) {
            updateBrickTransform(b);
            const minY = b.y - (Math.abs(b.sin) * b.hw + Math.abs(b.cos) * b.hh);
            if (minY < 0) {
              b.y -= minY;
              if (b.vy < 0) b.vy = 0;
              // Rolling/sliding friction when resting on the ground
              b.vx *= 0.975;
              b.omega *= 0.92;
            }
          }
        }
      }
    }

    // Update crash-test dummy head/torso spring inside cabin
    car.dummyPitch += car.dummyPitchVel * SUB_DT;
    car.dummyPitchVel += (-car.dummyPitch * 45 - car.dummyPitchVel * 6.5) * SUB_DT;
    car.dummyPitch = Math.max(-0.25, Math.min(0.65, car.dummyPitch));
  }

  // Post-frame support graph & sleep stabilization
  let movingCount = 0;
  if (impactOccurred) {
    for (let i = 0; i < bricks.length; i++) {
      const b = bricks[i];
      if (b.bonded || b.sleeping) continue;

      const speedSq = b.vx * b.vx + b.vy * b.vy;
      const angSpeed = Math.abs(b.omega);

      // Check if brick is moving perceptibly
      if (speedSq > 0.008 || angSpeed > 0.16) {
        movingCount++;
        b.sleepTimer = 0;
      } else {
        b.sleepTimer += FIXED_DT;
        // Gently damp micro-oscillations once nearly at rest
        b.vx *= 0.72;
        b.vy *= 0.72;
        b.omega *= 0.68;
        if (b.sleepTimer > 0.25) {
          b.vx = 0;
          b.vy = 0;
          b.omega = 0;
          b.sleeping = true;
        }
      }
    }

    const carMoving = Math.abs(car.vx) > 0.04 || Math.abs(car.vy) > 0.04 || Math.abs(car.omega) > 0.04;
    if (movingCount === 0 && !carMoving && simTime > 0.4) {
      settledTimer += FIXED_DT;
      if (settledTimer > 0.25) {
        car.vx = 0;
        car.vy = 0;
        car.omega = 0;
        simState = "settled";
        updateStatusUI("settled");
      }
    } else {
      settledTimer = 0;
    }
  }

  // Update visual particles
  for (let i = dustParticles.length - 1; i >= 0; i--) {
    const p = dustParticles[i];
    p.life += FIXED_DT;
    if (p.life >= p.maxLife) {
      dustParticles.splice(i, 1);
      continue;
    }
    p.x += p.vx * FIXED_DT;
    p.y += p.vy * FIXED_DT;
    if (p.isChip) {
      p.vy -= g * FIXED_DT;
      if (p.y < 0.02) {
        p.y = 0.02;
        p.vy = -p.vy * 0.3;
        p.vx *= 0.7;
      }
    } else {
      p.vx *= 0.95;
      p.vy += 0.35 * FIXED_DT;
      p.size += 12 * FIXED_DT;
    }
  }

  cameraShake *= 0.86;
  if (cameraShake < 0.1) cameraShake = 0;

  updateTelemetryUI();
}

// =========================================================================
// TELEMETRY & UI UPDATES
// =========================================================================
function getMovingBricksCount() {
  if (!impactOccurred) return 0;
  let count = 0;
  for (let i = 0; i < bricks.length; i++) {
    const b = bricks[i];
    if (!b.bonded && !b.sleeping && (b.vx * b.vx + b.vy * b.vy > 0.008 || Math.abs(b.omega) > 0.16)) {
      count++;
    }
  }
  return count;
}

function getDisplacedBricksCount() {
  let count = 0;
  for (let i = 0; i < bricks.length; i++) {
    const b = bricks[i];
    if (!b.bonded) {
      count++;
    }
  }
  return count;
}

      function updateStatusUI(state) {
        statusPill.className = "status-pill";
        if (state === "running") {
          statusPill.classList.add("running");
          statusText.textContent = "Testing";
        } else if (state === "settled") {
          statusPill.classList.add("settled");
          statusText.textContent = "Settled";
        } else {
          statusText.textContent = "Ready";
        }
      }

      function updateTelemetryUI() {
        const displaySpeed = simState === "ready" ? settings.carSpeed : Math.abs(car.vx);
        const kmh = Math.round(displaySpeed * 3.6);
        telSpeed.textContent = displaySpeed.toFixed(1);
        telSpeedKmh.textContent = "m/s (" + kmh + " km/h)";

        telTime.textContent = simTime.toFixed(2);

        const totalBricks = bricks.length;
        const movingCount = getMovingBricksCount();
        const displacedCount = getDisplacedBricksCount();
        const displacedPct = totalBricks > 0 ? Math.round((displacedCount / totalBricks) * 100) : 0;

        telMoving.textContent = String(movingCount);
        telTotalBricks.textContent = "/ " + totalBricks;

        telDisplaced.textContent = String(displacedCount);
        telDisplacedPct.textContent = "(" + displacedPct + "%)";

        const totalWallMass = totalBricks * settings.brickMass;
        telWallMass.textContent = totalWallMass.toFixed(1);

        telPeakG.textContent = peakGForce.toFixed(1) + " G";
        telImpulse.textContent = (totalMomentumTransferred / 1000).toFixed(1) + " kN\u00B7s";
      }

      function syncSettingsLabels() {
        valCarSpeed.textContent = settings.carSpeed + " m/s";
        valWallCols.textContent = settings.wallColumns + " bricks";
        valWallRows.textContent = settings.wallRows + " bricks";
        valWallLayers.textContent = settings.wallDepthLayers + (settings.wallDepthLayers === 1 ? " layer" : " layers");
        valBrickMass.textContent = settings.brickMass.toFixed(1) + " kg";
      }

      // =========================================================================
      // RENDERING (80 PIXELS PER METER BASELINE SCALE)
      // =========================================================================
      function resizeCanvas() {
        const dpr = window.devicePixelRatio || 1;
        const rect = stage.getBoundingClientRect();
        canvas.width = Math.max(1, Math.floor(rect.width * dpr));
        canvas.height = Math.max(1, Math.floor(rect.height * dpr));
      }

      function renderScene() {
        const dpr = window.devicePixelRatio || 1;
        const cw = canvas.width / dpr;
        const ch = canvas.height / dpr;

        ctx.save();
        ctx.scale(dpr, dpr);

        // Compute effective scale (80 px/m baseline, gently scaled only if viewport is smaller than initial scene)
        const baseScale = DEFAULTS.scale;
        const wallFrontX = TRACK_START_X + DEFAULTS.carWidth + RUNWAY_GAP;
        const wallWidthM = settings.wallColumns * DEFAULTS.brickWidth + 0.5;
        const minVisibleWidthM = wallFrontX + wallWidthM + 1.4;
        const fitScaleX = cw / Math.max(15.2, minVisibleWidthM);
        const scale = Math.min(baseScale, fitScaleX);

        // Smooth camera pan if high-speed car travels beyond initial right edge
        const maxVisibleX = cw / scale;
        let targetCamX = 0;
        if (simState !== "ready" && car.x + 5.0 > maxVisibleX) {
          targetCamX = (car.x + 5.0) - maxVisibleX;
        }
        cameraX += (targetCamX - cameraX) * 0.12;

        const groundScreenY = ch - Math.max(64, ch * 0.15);

        // Apply deterministic screen-space impact shake
        let shakeDx = 0;
        let shakeDy = 0;
        if (cameraShake > 0.1) {
          shakeDx = Math.sin(simTime * 95) * cameraShake;
          shakeDy = Math.cos(simTime * 115) * cameraShake * 0.7;
        }

        // 1. Background Sky & Test Facility Backdrop
        const skyGrad = ctx.createLinearGradient(0, 0, 0, groundScreenY);
        skyGrad.addColorStop(0, "#0b111e");
        skyGrad.addColorStop(0.65, "#131c2e");
        skyGrad.addColorStop(1, "#1c283d");
        ctx.fillStyle = skyGrad;
        ctx.fillRect(0, 0, cw, groundScreenY);

        ctx.save();
        ctx.translate(shakeDx - cameraX * scale, shakeDy);

        // Photogrammetry Background Calibration Grid (1m and 0.5m world grid)
        drawCalibrationGrid(scale, groundScreenY, cw / scale + cameraX + 4);

        // 2. Ground Plane, Sub-base & Asphalt Test Track
        drawGroundAndTrack(scale, groundScreenY, cw / scale + cameraX + 6);

        // 3. Tire Skid Marks
        drawSkidMarks(scale, groundScreenY);

        // 4. Staggered Physical Brick Wall (back depth layers to front layer)
        drawBricks(scale, groundScreenY);

        // 5. Test Vehicle (Car Body, Cabin, Crash Dummy, Wheels, Fiducial Targets)
        drawCar(scale, groundScreenY);

        // 6. Impact Dust & Mortar Chips
        drawDustParticles(scale, groundScreenY);

        ctx.restore();
        ctx.restore();
      }

      function drawCalibrationGrid(scale, groundY, maxWorldX) {
        // Subtle 1-meter engineering grid lines
        ctx.strokeStyle = "rgba(148, 163, 184, 0.055)";
        ctx.lineWidth = 1;
        ctx.beginPath();
        for (let m = 0; m <= maxWorldX; m += 1) {
          const x = m * scale;
          ctx.moveTo(x, 0);
          ctx.lineTo(x, groundY);
        }
        for (let m = 1; m <= 8; m += 1) {
          const y = groundY - m * scale;
          if (y < 0) break;
          ctx.moveTo(0, y);
          ctx.lineTo(maxWorldX * scale, y);
        }
        ctx.stroke();

        // Crash test facility photogrammetry backdrop wall & height scale near impact zone
        const wallFrontX = TRACK_START_X + DEFAULTS.carWidth + RUNWAY_GAP;
        const rulerX = (wallFrontX - 0.55) * scale;
        ctx.strokeStyle = "rgba(56, 189, 248, 0.28)";
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(rulerX, groundY);
        ctx.lineTo(rulerX, groundY - 4.0 * scale);
        ctx.stroke();

        ctx.fillStyle = "rgba(148, 163, 184, 0.55)";
        ctx.font = "600 10px " + getComputedStyle(document.body).getPropertyValue("--font-mono");
        ctx.textAlign = "right";
        for (let h = 1; h <= 4; h++) {
          const py = groundY - h * scale;
          if (py > 14) {
            ctx.fillRect(rulerX - 5, py, 5, 1);
            ctx.fillText(h + ".0m", rulerX - 8, py + 3);
          }
        }

        // Impact plane marker line
        const impactLineX = wallFrontX * scale;
        ctx.save();
        ctx.setLineDash([4, 4]);
        ctx.strokeStyle = "rgba(249, 115, 22, 0.35)";
        ctx.beginPath();
        ctx.moveTo(impactLineX, groundY);
        ctx.lineTo(impactLineX, groundY - 3.2 * scale);
        ctx.stroke();
        ctx.restore();
      }

      function drawGroundAndTrack(scale, groundY, maxWorldX) {
        const trackEndPx = maxWorldX * scale;

        // Deep soil / concrete sub-grade
        const groundGrad = ctx.createLinearGradient(0, groundY, 0, groundY + 120);
        groundGrad.addColorStop(0, "#1e293b");
        groundGrad.addColorStop(0.18, "#0f172a");
        groundGrad.addColorStop(1, "#060911");
        ctx.fillStyle = groundGrad;
        ctx.fillRect(0, groundY, trackEndPx, 160);

        // Asphalt surface strip
        ctx.fillStyle = "#334155";
        ctx.fillRect(0, groundY, trackEndPx, 8);

        // High-visibility crash test curb stripes every 1.0 meter
        for (let m = 0; m < maxWorldX; m++) {
          ctx.fillStyle = (m % 2 === 0) ? "#cbd5e1" : "#475569";
          ctx.fillRect(m * scale, groundY + 8, scale, 4);
        }

        // Top surface crisp horizon line
        ctx.strokeStyle = "#94a3b8";
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(0, groundY);
        ctx.lineTo(trackEndPx, groundY);
        ctx.stroke();

        // Distance markers in meters along the track
        ctx.fillStyle = "#94a3b8";
        ctx.font = "600 10px monospace";
        ctx.textAlign = "center";
        for (let m = 0; m <= maxWorldX; m++) {
          const x = m * scale;
          const isMajor = (m % 5 === 0);
          ctx.strokeStyle = isMajor ? "rgba(248, 250, 252, 0.55)" : "rgba(148, 163, 184, 0.25)";
          ctx.beginPath();
          ctx.moveTo(x, groundY + 12);
          ctx.lineTo(x, groundY + (isMajor ? 22 : 17));
          ctx.stroke();

          if (isMajor || m === Math.round(TRACK_START_X + DEFAULTS.carWidth + RUNWAY_GAP)) {
            ctx.fillText(m + "m", x, groundY + 34);
          }
        }
      }

      function drawSkidMarks(scale, groundY) {
        if (skidMarks.length === 0) return;
        for (let i = 0; i < skidMarks.length; i++) {
          const s = skidMarks[i];
          ctx.fillStyle = "rgba(15, 23, 42, " + s.alpha.toFixed(2) + ")";
          ctx.fillRect(s.x * scale, groundY - 1.5, s.w * scale, 4);
        }
      }

      function drawBricks(scale, groundY) {
        const layers = settings.wallDepthLayers;

        // Render from backmost depth layer (layers - 1) to frontmost layer (0)
        for (let l = layers - 1; l >= 0; l--) {
          const layerBricks = bricksByLayer[l];
          if (!layerBricks) continue;

          // Subtle 2.5D depth projection offset for back layers so overlapping wythes are clearly visible
          const depthPxX = l * 4.5;
          const depthPxY = -l * 3.5;
          const layerDarken = l * 0.14;

          for (let i = 0; i < layerBricks.length; i++) {
            const b = layerBricks[i];
            const px = b.x * scale + depthPxX;
            const py = groundY - b.y * scale + depthPxY;
            const pw = b.w * scale;
            const ph = b.h * scale;

            ctx.save();
            ctx.translate(px, py);
            ctx.rotate(-b.angle);

            // Terracotta brick palette with deterministic variation & depth shading
            const baseR = Math.round((196 - b.shade * 26) * (1 - layerDarken));
            const baseG = Math.round((78 - b.shade * 16) * (1 - layerDarken));
            const baseB = Math.round((52 - b.shade * 12) * (1 - layerDarken));

            // Mortar bed border / outer brick body
            ctx.fillStyle = "rgb(" + baseR + "," + baseG + "," + baseB + ")";
            ctx.strokeStyle = (l === 0) ? "rgba(226, 232, 240, 0.68)" : "rgba(148, 163, 184, 0.38)";
            ctx.lineWidth = 1.1;

            ctx.beginPath();
            ctx.rect(-pw * 0.5, -ph * 0.5, pw, ph);
            ctx.fill();
            ctx.stroke();

            // Inner brick bevel highlight
            ctx.fillStyle = "rgba(255, 255, 255, 0.08)";
            ctx.fillRect(-pw * 0.5 + 1.5, -ph * 0.5 + 1.5, pw - 3, 2.5);

            // Subtle masonry frog / core indentation detail
            ctx.fillStyle = "rgba(0, 0, 0, 0.16)";
            ctx.fillRect(-pw * 0.28, -ph * 0.16, pw * 0.56, ph * 0.32);

            ctx.restore();
          }
        }
      }

      function drawCar(scale, groundY) {
        if (!car) return;

        const px = car.x * scale;
        const py = groundY - car.y * scale;
        const hw = car.hw * scale;
        const hh = car.hh * scale;
        const crumplePx = car.crumple * scale;

        ctx.save();
        ctx.translate(px, py);
        ctx.rotate(-car.angle);

        // Ground shadow beneath car
        ctx.fillStyle = "rgba(0, 0, 0, 0.42)";
        ctx.beginPath();
        ctx.ellipse(0, hh - 2, hw * 0.92, 6, 0, 0, Math.PI * 2);
        ctx.fill();

        const frontX = hw - crumplePx;
        const hoodBuckleY = -crumplePx * 0.22;

        // 1. Main Vehicle Chassis Silhouette (4.2m wide x 1.45m tall)
        const bodyGrad = ctx.createLinearGradient(0, -hh, 0, hh);
        bodyGrad.addColorStop(0, "#fb923c");
        bodyGrad.addColorStop(0.45, "#f97316");
        bodyGrad.addColorStop(0.85, "#c2410c");
        bodyGrad.addColorStop(1, "#7c2d12");

        ctx.fillStyle = bodyGrad;
        ctx.strokeStyle = "#fed7aa";
        ctx.lineWidth = 1.4;

        ctx.beginPath();
        ctx.moveTo(-hw, hh - 10);                         // rear lower bumper
        ctx.lineTo(frontX - 6, hh - 8);                   // underbody sill
        ctx.lineTo(frontX, hh - 20);                      // front air dam / bumper nose
        ctx.lineTo(frontX - 3, hh - 64 + hoodBuckleY);    // front grille top
        ctx.lineTo(hw * 0.44, hh - 68 + hoodBuckleY * 1.4); // hood buckle / cowl
        ctx.lineTo(hw * 0.34, -hh + 4);                   // windshield header / roof front
        ctx.lineTo(-hw * 0.46, -hh + 4);                  // roof rear
        ctx.lineTo(-hw * 0.78, hh - 66);                  // rear window base / C-pillar
        ctx.lineTo(-hw, hh - 60);                         // trunk deck
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Dark lower rocker panel & bumpers
        ctx.fillStyle = "#1e293b";
        ctx.fillRect(-hw, hh - 16, hw + frontX - 2, 9);

        // 2. Cabin Greenhouse (Windows, B-Pillar, Crash-Test Dummy & Airbag)
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(hw * 0.40, hh - 65);
        ctx.lineTo(hw * 0.31, -hh + 10);
        ctx.lineTo(-hw * 0.43, -hh + 10);
        ctx.lineTo(-hw * 0.72, hh - 64);
        ctx.closePath();
        ctx.fillStyle = "#0f172a";
        ctx.fill();
        ctx.clip();

        // Tinted window reflection
        const winGrad = ctx.createLinearGradient(0, -hh, 0, hh - 60);
        winGrad.addColorStop(0, "rgba(56, 189, 248, 0.25)");
        winGrad.addColorStop(1, "rgba(15, 23, 42, 0.85)");
        ctx.fillStyle = winGrad;
        ctx.fillRect(-hw, -hh, hw * 2, hh);

        // Deployed Airbag (if triggered by impact)
        if (car.airbagDeployed) {
          ctx.fillStyle = "rgba(248, 250, 252, 0.92)";
          ctx.strokeStyle = "#94a3b8";
          ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.arc(hw * 0.23, hh - 80, 14, 0, Math.PI * 2);
          ctx.fill();
          ctx.stroke();
        }

        // Crash-Test Dummy Silhouette (tilts forward on deceleration)
        ctx.save();
        ctx.translate(hw * 0.04, hh - 62);
        ctx.rotate(car.dummyPitch);
        // Torso
        ctx.fillStyle = "#facc15";
        ctx.fillRect(-6, -22, 12, 22);
        // Seatbelt strap
        ctx.strokeStyle = "#111827";
        ctx.lineWidth = 2.5;
        ctx.beginPath();
        ctx.moveTo(-6, -20);
        ctx.lineTo(6, -2);
        ctx.stroke();
        // Dummy Head with fiducial cross
        ctx.fillStyle = "#facc15";
        ctx.beginPath();
        ctx.arc(1, -30, 7.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#111827";
        ctx.beginPath();
        ctx.arc(1, -30, 3, 0, Math.PI, true);
        ctx.fill();
        ctx.restore();

        // B-Pillar
        ctx.fillStyle = "#1e293b";
        ctx.fillRect(-10, -hh + 8, 8, hh);
        ctx.restore();

        // 3. Crash-Test Livery Stripes & Photogrammetry Fiducial Targets
        ctx.fillStyle = "#111827";
        ctx.fillRect(-hw * 0.55, hh - 46, hw * 1.1, 8);

        drawFiducialMarker(-hw * 0.45, hh - 42, 7.5);
        drawFiducialMarker(hw * 0.12, hh - 42, 7.5);
        drawFiducialMarker(frontX - 36, hh - 42, 6.5);

        // Headlight & Taillight
        ctx.fillStyle = car.crumple > 0.08 ? "#94a3b8" : "#fef08a";
        ctx.fillRect(frontX - 9, hh - 55, 8, 12);
        ctx.fillStyle = "#ef4444";
        ctx.fillRect(-hw + 1, hh - 54, 7, 13);

        // 4. Front & Rear Wheels with Rotating Fiducial Quadrants
        const wheelR = 0.34 * scale;
        const rearWheelX = -hw * 0.60;
        const frontWheelX = Math.min(hw * 0.60, frontX - wheelR - 6);
        const wheelY = hh - wheelR;

        drawWheel(rearWheelX, wheelY, wheelR, car.wheelAngle);
        drawWheel(frontWheelX, wheelY, wheelR, car.wheelAngle);

        ctx.restore();
      }

      function drawFiducialMarker(x, y, r) {
        ctx.save();
        ctx.translate(x, y);
        ctx.fillStyle = "#facc15";
        ctx.beginPath();
        ctx.arc(0, 0, r, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = "#111827";
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.arc(0, 0, r, 0, Math.PI * 0.5);
        ctx.closePath();
        ctx.fill();

        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.arc(0, 0, r, Math.PI, Math.PI * 1.5);
        ctx.closePath();
        ctx.fill();

        ctx.strokeStyle = "#111827";
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.arc(0, 0, r, 0, Math.PI * 2);
        ctx.stroke();
        ctx.restore();
      }

      function drawWheel(wx, wy, r, angle) {
        ctx.save();
        ctx.translate(wx, wy);

        // Wheel arch cutout shadow
        ctx.fillStyle = "#090d16";
        ctx.beginPath();
        ctx.arc(0, 0, r + 4, 0, Math.PI * 2);
        ctx.fill();

        ctx.rotate(angle);

        // Rubber tire
        ctx.fillStyle = "#1e293b";
        ctx.strokeStyle = "#0f172a";
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(0, 0, r, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();

        // Alloy rim
        const rimR = r * 0.64;
        ctx.fillStyle = "#cbd5e1";
        ctx.beginPath();
        ctx.arc(0, 0, rimR, 0, Math.PI * 2);
        ctx.fill();

        // Crash test wheel rotation fiducial quadrants
        drawFiducialMarker(0, 0, rimR * 0.78);

        ctx.restore();
      }

      function drawDustParticles(scale, groundY) {
        for (let i = 0; i < dustParticles.length; i++) {
          const p = dustParticles[i];
          const px = p.x * scale;
          const py = groundY - p.y * scale;
          const fade = Math.max(0, 1 - p.life / p.maxLife);
          const alpha = p.alpha * fade;

          if (p.isChip) {
            ctx.fillStyle = "rgba(180, 83, 58, " + alpha.toFixed(2) + ")";
            ctx.fillRect(px - p.size * 0.5, py - p.size * 0.5, p.size, p.size);
          } else {
            ctx.fillStyle = "rgba(203, 213, 225, " + alpha.toFixed(2) + ")";
            ctx.beginPath();
            ctx.arc(px, py, p.size, 0, Math.PI * 2);
            ctx.fill();
          }
        }
      }

      // =========================================================================
      // EVENT LISTENERS & CONTROLS
      // =========================================================================
      function onSettingInput() {
        settings.carSpeed = parseFloat(inpCarSpeed.value);
        settings.wallColumns = parseInt(inpWallCols.value, 10);
        settings.wallRows = parseInt(inpWallRows.value, 10);
        settings.wallDepthLayers = parseInt(inpWallLayers.value, 10);
        settings.brickMass = parseFloat(inpBrickMass.value);

        syncSettingsLabels();
        resetExperiment();
      }

      inpCarSpeed.addEventListener("input", onSettingInput);
      inpWallCols.addEventListener("input", onSettingInput);
      inpWallRows.addEventListener("input", onSettingInput);
      inpWallLayers.addEventListener("input", onSettingInput);
      inpBrickMass.addEventListener("input", onSettingInput);

      btnTest.addEventListener("click", function () {
        startExperiment();
      });

      btnReset.addEventListener("click", function () {
        resetExperiment();
      });

      btnDefaults.addEventListener("click", function () {
        settings.carSpeed = DEFAULTS.carSpeed;
        settings.wallColumns = DEFAULTS.wallColumns;
        settings.wallRows = DEFAULTS.wallRows;
        settings.wallDepthLayers = DEFAULTS.wallDepthLayers;
        settings.brickMass = DEFAULTS.brickMass;

        inpCarSpeed.value = String(DEFAULTS.carSpeed);
        inpWallCols.value = String(DEFAULTS.wallColumns);
        inpWallRows.value = String(DEFAULTS.wallRows);
        inpWallLayers.value = String(DEFAULTS.wallDepthLayers);
        inpBrickMass.value = String(DEFAULTS.brickMass);

        syncSettingsLabels();
        resetExperiment();
      });

      window.addEventListener("keydown", function (e) {
        if (e.target && e.target.tagName === "INPUT") return;
        if (e.code === "Space" || e.code === "Enter") {
          e.preventDefault();
          startExperiment();
        } else if (e.code === "KeyR") {
          e.preventDefault();
          resetExperiment();
        }
      });

      window.addEventListener("resize", function () {
        resizeCanvas();
        renderScene();
      });

      // =========================================================================
      // MAIN ANIMATION LOOP
      // =========================================================================
      function tick() {
        stepPhysics();
        renderScene();
        requestAnimationFrame(tick);
      }

      // Initialize default state on first load
      resizeCanvas();
      syncSettingsLabels();
      resetExperiment();
      requestAnimationFrame(tick);
    })();
  </script>
</body>
</html>
